-- Пользовательские и серверные задания.
-- Этот файл загружается после стандартной базы, поэтому одинаковый ID здесь
-- переопределяет стандартный перевод.
--
-- Формат:
-- RUQL_QUESTS[ID] = {
--     "Название",
--     "Описание",
--     "Цель задания",
--     "Текст прогресса у NPC",
--     "Текст завершения у NPC",
--     "Задача 1", "Задача 2", "Задача 3", "Задача 4",
--     originalTitle = "Точное английское название"
-- }
--
-- Пример (уберите -- в начале строк и замените данные):
-- RUQL_QUESTS[90001] = {
--     "Секреты Глиттермурка",
--     "Найдите записи разведчика и вернитесь ко мне.",
--     "Найдите записи разведчика.",
--     "Вы нашли записи?",
--     "Прекрасная работа, $N!",
--     "Записи разведчика", nil, nil, nil,
--     originalTitle = "Secrets of Glittermurk"
-- }

RUQL_QUESTS = RUQL_QUESTS or {}

-- Project Epoch: текст собран игровым коллектором 2026-09-05.
RUQL_QUESTS[26781] = {
    "Зацепка о камне Линуса",
    "Вот где мне понадобится твоя помощь, $N. Я недавно узнал, что мой бывший помощник сотрудничает с местным Братством Справедливости. Линус докладывал им о патрулях стражи Златоземья и обозах прямо у меня под носом!$B$BК несчастью, когда я его уволил, он украл у меня несколько артефактов. А тебе особенно не повезло — он забрал неактивный камень перемещения. Верни мне этот камень, и я с радостью помогу тебе.",
    "Принесите истощенный камень перемещения Залдимару в трактир «Гордость льва» в Златоземье.",
    "У тебя уже есть истощенный камень перемещения, $N? Линус оставил их, когда сбежал к Братству Справедливости. Один из них понадобится мне для следующего этапа.",
    "Истощенный камень перемещения! Как раз то, что нужно, $N. Мой бывший помощник Линус оказался предателем и выдавал Братству Справедливости мои тайны. Но его камни все еще работают, и этому я найду применение.",
    "Истощенный камень перемещения", nil, nil, nil,
    originalTitle = "Linus Stone Tips"
}

