RUQL_QUESTS[26774] = {
    "Паучий эликсир",
    "$N, ты поможешь мне? Эти бедные шахтёры были найдены бегущими из Яшмовой шахты. Они рухнули без сил, не дойдя до Златоземья. Я не смог понять, что случилось — они бредят, будто что-то помутило их рассудок.$B$BХодят слухи, что глубоко в шахте свили гнездо пауки. Если шахтёров отравили пауки, это всё объяснило бы! Мне нужен образец жвал рудничного паука, чтобы приготовить противоядие.$B$BИ, пожалуйста, если увидишь ещё пленённых шахтёров — освободи их, чтобы они могли выбраться.",
    "Добудьте 4 жвала рудничного паука и освободите 4 пленённых шахтёров из Яшмовой шахты в Элвиннском лесу.",
