}

-- Project Epoch: текст собран отчётом аддона 2026-09-06.
-- Цепочка "Barroom Blitz" (26689-26695) — во всех частях одинаковое название
-- квеста. Описание/цель — из базы pfQuest-epoch, прогресс/завершение — из
-- живого отчёта, где они были захвачены.
RUQL_QUESTS[26689] = {
    "Кабацкая потасовка",
    "Всего пару часов назад мне пришлось разнимать драку в трактире «Гордость льва». Из-за чего? Любовь? Честь? Деньги? Нет. Из-за зелья. Одного-единственного проклятого зелья ярости.$B$BКогда я растащил драчунов, в одном из них я узнал Мардигана, сына архимага Карлейна, хозяина Башни Азоры к востоку отсюда.$B$BМардиган, шатаясь, побрёл по дороге на юго-запад от города, в сторону Вестбрукского гарнизона. Не проверишь, как он там? Если с ним что-то случится, его отец обрушится на местную стражу, как тонна кирпичей.",
    "Найдите Мардигана на дороге к юго-западу от Златоземья.",
    nil, nil, nil, nil, nil, nil,
    originalTitle = "Barroom Blitz"
}

RUQL_QUESTS[26690] = {
    "Кабацкая потасовка",
    "Отец послал меня в трактир «Гордость льва», чтобы попросить Уильяма Пестла сварить ему зелье ярости. Получив зелье, я подумал: почему бы заодно не пропустить кружку эля? Но не успел я осушить и половины кружки, как на меня набросился какой-то незнакомый мне мерзавец!$B$BДело быстро приняло скверный оборот, и как раз когда мы уже были готовы схватиться за клинки, вмешался маршал Дуган. В суматохе этот мерзавец украл зелье!$B$BПризнаю, я уже не раз подводил отца с его поручениями, и если у меня не будет этого зелья, он точно выгонит меня и мою собаку взашей.$B$BЕсли тебя прислал маршал Дуган — пожалуйста, собери листья кровавого лепестка и отнеси их Уильяму Пестлу, чтобы он сварил мне новое зелье.",
    "Соберите 6 листьев кровавого лепестка в Элвиннском лесу и отнесите их Уильяму Пестлу в трактир «Гордость льва».",
    nil, nil, nil, nil, nil, nil,
    originalTitle = "Barroom Blitz"
}

RUQL_QUESTS[26691] = {
    "Кабацкая потасовка",
    "Я больше не хочу иметь дела с Мардиганом, раз он устраивает такой переполох. Трактир «Гордость льва» — уютное и почтенное заведение, а стоит ему появиться — снова драка!$B$BЕсли ему нужны зелья и флаконы — пусть теперь идёт в Штормград. Передай ему, что теперь он забота мисс Люмьер!",
    "Вернитесь к Мардигану, к юго-западу от Златоземья.",
    "Вернулся из «Гордости льва», $N? Пестл наконец приготовил отцовское зелье ярости, или всё ещё дуется из-за той стычки?",
    "Пестл больше не хочет иметь со мной дела? <Мардиган хмурится.> Ладно. Одна маленькая заварушка — и с тобой обращаются как с преступником, $N. Но зелье готово, хотя бы это радует.",
