RUQL_QUESTS[28494] = {
    "Заказ для Джейсона Мазерса",
    "У меня совсем не осталось мелкой рыбёшки. Продал последнюю сегодня утром повару, который был готов за неё драться.$B$BЕсли у тебя есть удочка и твёрдая рука, мне бы не помешал свежий улов. Принеси 20 сырых блестящих мелких рыбёшек. Народ здесь рассчитывает, что у меня всегда есть запасы, а отказывать им не хочется.",
    "Джейсон Мазерс просит вас, используя навык рыбной ловли, собрать 20 сырых блестящих мелких рыбёшек и доставить заказ Джейсону Мазерсу у Хрустального озера в Элвиннском лесу.",
