RUQL_QUESTS[26768] = {
    "Сладкая месть",
    "Наш славный хозяин пригласил особых гостей на ужин, и мне поручили приготовить угощение. Я потратила недели на поиск лучших ингредиентов и лучших рецептов, чтобы устроить им незабываемый ужин.$B$BВ тот особый день я часами не выходила из кухни, доводя до идеала каждую специю и соус. И только когда была уверена, что блюдо покорит их вкус, позволила подавать его на стол.$B$BСначала всё шло прекрасно. Гости истекали слюной в предвкушении, вдыхая аромат закусок. Когда всех обслужили, наш Хозяин пригласил всех «приступать».$B$BИ вот тогда я получила самое большое оскорбление в своей жизни. Даже не попробовав еду, Хозяин щёлкнул пальцами и наколдовал себе кекс! Он ещё и пошутил, что у него зависимость от выпечки, и не притронулся ни к кусочку моего пиршества. А потом и гости захотели того же, что у него! Всё пропало зря!$B$BМне надоела его неблагодарность, и у меня есть план мести. Мне нужно лишь несколько ингредиентов, которых не хватает.$B$BПринеси мне немного мана-ягод из сада, за которым ухаживает Джинджер, а также муку, лёгкие специи и соль у Тарина Баудена в Златоземье.",
    "Принесите Саре Темплворт ингредиенты, необходимые для особого угощения.",
    "Ты уже принёс ингредиенты, $N? Хозяин пригласил особых гостей, и я не собираюсь его разочаровывать. Только самое лучшее подойдёт.",
    "Все самые лучшие ингредиенты, точно как я просила! Гости нашего хозяина отобедают на славу, $N, ещё как. <Улыбка Сары чуть слишком сладкая для обычной радости.> Теперь начинается выпечка.",
    originalTitle = "Just Desserts"
}

-- Цепочка "Just Desserts" продолжается: Сара мстит архимагу Теокриту
-- слабительным пирогом за то, что он пренебрёг её угощением ради выпечки.
RUQL_QUESTS[26769] = {
    "Сладкая месть",
    "Хорошо, теперь, когда ты принёс мне ингредиенты, я испеку восхитительный пирог — но нужна ещё одна вещь: что-то с очень насыщенным вкусом, что перебьёт все остальные вкусы в пироге.$B$BБлижайший колодец никто не использует, потому что его отравили эксперименты Хозяина. Уверена, там найдётся то, что нам нужно. Возьми эту удочку и налови мне отравленной магией тины.",
    "Наловите отравленной магией тины в колодце рядом с Башней Азоры.",
    "Ты уже наловил отравленной магией тины из колодца, $N? Нужен всего один ингредиент — что-то, что перебьёт лишнюю горечь.",
    "Отравленная магией тина, отлично! <Сара хихикает.> Насыщенный вкус, который перебьёт всё остальное, $N. Снаружи пирог выглядит восхитительно. А что внутри — это уже наш с тобой секрет.",
    originalTitle = "Just Desserts"
}

RUQL_QUESTS[26770] = {
    "Сладкая месть",
    "Вот и всё, пирог готов. Снаружи — совершенно восхитительный... но внутри даже один маленький кусочек гарантированно вызовет у едока сильные спазмы желудка.$B$BОтнеси пирог Теокриту на вершину башни. Думаю, это вылечит его зависимость от выпечки. Тогда он будет есть полезную и вкусную еду, которую готовлю я, и без жалоб.",
    "Преподнесите пирог Сары Теокриту.",
    nil,
    "Пирог? Мне? <Теокрит разглядывает его.> От Сары Темплворт, говоришь? Как мило с её стороны. <Он откладывает пирог в сторону, ничего не подозревая.> Передай ей мою благодарность, $N. Полакомлюсь им позже.",
