RUQL_QUESTS[26771] = {
    "Потерянное снаряжение",
    "Я работал на Яшмовой шахте, пока её не захватили кобольды и пауки. Она была богата рудой и служила основным источником сырья для кузнецов Штормграда.$B$BКогда чудовища захватили шахту, мы потеряли многих братьев и сестёр-шахтёров и всё наше снаряжение. Шахтёров мне не вернуть, но не мог бы ты найти часть снаряжения, которое мы там оставили, и принести его мне?",
    "Добудьте 8 единиц горняцкого снаряжения в Яшмовой шахте, затем вернитесь к Роберту Мистону в Златоземье.",
    nil, nil,
