RUQL_QUESTS[26794] = {
    "Розыск: Большой Синий",
    "Архимаги Башни Азоры, может, и блестящие умы, но с управлением рисками у них... не очень.$B$BК несчастью для нас, одна бабочка подлетела слишком близко к очередному эксперименту хозяина и мутировала во что-то невменяемое.$B$BПочти каждую ночь она разоряет наш сад, и качество нашей еды от этого сильно страдает!$B$BРазберись с этой тварью и принеси её крыло Джинджер Макгаббинс в Башню Азоры! В последний раз её видели к северо-востоку от башни, вдоль побережья озера Каменных Курганов.",
