-- Project Epoch: пакет переведён по базе pfQuest-epoch (db/enUS/quests-epoch.lua)
-- 2026-09-06. Хаб рыболовных заданий старика Барло в деревне Чернопасть,
-- Азшара (ID 26100-26125) — не цепочка по pre/next, а набор параллельных
-- заданий от одного рассказчика с двумя помощниками (Уифла и Орсооха),
-- поэтому идёт единым блоком. Текст прогресса/завершения у NPC у pfQuest
-- не хранится (только T/O/D) — оставлен nil до живого сбора.
RUQL_QUESTS[26100] = {
    "Крокотопы в городе",
    "Здравствуй, $C. Рад, что ты заглянул перемолвиться словечком со стариком — дома у нас беда стряслась.$B$BБродячий торговец недавно продал партию детёнышей крокотопов доверчивым ребятишкам. Крокотоп — зверь дикий, вот многие и сбежали, теперь шныряют по городским водостокам.$B$BБери свою самую крепкую удочку, закинь леску в любом из столичных городов и притащи мне одного из этих чертенят. Ух, не терпится на такого поглядеть.",
    "Поймайте детёныша крокотопа в Оргриммаре и верните его старику Барло в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Детёныш крокотопа", nil, nil, nil,
    originalTitle = "Crocolisks in the City"
}

