RUQL_QUESTS[26102] = {
    "Призраки в реке",
    "В своё время рыбалка у старого Каражана была знатная. А потом всё это безобразие с Легионом, демонами да с уходом Медива... От одной мысли об этом месте кости трещат.$B$BМоему другу Орсоохе стало любопытно, можно ли там до сих пор рыбачить. Мне стыдно было признаться, что я сам боюсь, вот я и пообещал попытать счастья. Да только не могу себя заставить туда сунуться — суеверный я, как и все рыбаки.$B$BМожет, ты бы сходил проверить да принёс ему, что попадётся на крючок?",
    "Поймайте призрачную рыбу-спектра в Перевале Мертвого Ветра и отнесите её Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Призрачная рыба-спектр", nil, nil, nil,
    originalTitle = "Ghosts in the River"
}

RUQL_QUESTS[26103] = {
    "Замороженные запасы",
    "Знаешь, рыбалка годится не только для того, чтоб раздобыть себе ужин. Иной раз она и в жаркий денёк выручит.$B$BВозьмём, к примеру, воды Зимних Ключей — там можно выловить здоровенные глыбы льда, что не тают днями напролёт, промёрзли насквозь. То, что нужно, чтобы хранить рыбу при перевозке — или запустить в кого-нибудь, кто не так на тебя посмотрел.$B$BА у меня они как раз кончаются. Не пополнишь запасы? Как закончишь — отнеси Уифле.",
    "Соберите 10 ледяных комьев в Зимних Ключах и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Ледяной ком", nil, nil, nil,
    originalTitle = "Frozen Supplies"
}

RUQL_QUESTS[26104] = {
    "Рыбалка за произведениями искусства",
    "Знаешь, в реках, озёрах да морях мира оседает всякой всячины немало. И кое-что из этого даже чего-то да стоит!$B$BВозьми хоть изделия ремесленников да предметы искусства, что вышли когда-то из мельницы Броумана в нынешних Восточных Чумных землях. Были там прелестные вещицы — пейзажи да резные фигурки из дерева, как раз по вкусу Орсоохе. Может, что-то из этого прибило к берегу тех озёр, что там ещё остались? Стоит поискать, а?",
    "Найдите изысканный пейзаж в Восточных Чумных землях и отнесите его Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Изысканный пейзаж", nil, nil, nil,
    originalTitle = "Fishing for Fine Art"
}

RUQL_QUESTS[26105] = {
    "Цепкий тумпфиш",
    "Река Торидал, что впадает в озеро Дарроумир в нынешних Западных Чумных землях, всегда была не из лёгких для рыбалки. А уж для этих старых костей — тем более, врать не буду.$B$BЕсли ищешь испытание, там можно выловить тумпфиша. Уифла будет очень впечатлена, уж поверь. Только берегись тамошних мельниц — говорят, они там все чумные теперь.",
    "Поймайте 10 тумпфишей в Западных Чумных землях и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Тумпфиш", nil, nil, nil,
    originalTitle = "The Tenacious Tumpfish"
}

RUQL_QUESTS[26106] = {
    "Огнеупорные лобстеры",
    "Эх, Пылающие степи... запах серы и эля. Самое то настроение, чтобы взять удочку да отправиться в путь. Там, кроме лавы, ничего и нет, а рыбу всё равно можно наловить на целый пир. Я про знаменитого огнеупорного лобстера. Панцирь крепче гвоздей, огню не поддаётся, а вот сними его — и внутри такой пряный, дымный вкус, что пальчики оближешь.$B$BУ Орсоохи как раз есть чем эти панцири вскрывать, так что неси ему, как наберёшь достаточно на всех.",
    "Поймайте 10 огнеупорных лобстеров в Пылающих степях и отнесите их Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Огнеупорный лобстер", nil, nil, nil,
    originalTitle = "Lava-proof Lobsters"
}

RUQL_QUESTS[26107] = {
    "Рыбный парфюм",
    "Никогда мне не понять моду, $N. Особенно моду фурболгов. Уифла говорит, что племя Чернопасти делает духи из рыбы, которую они раньше добывали в нынешнем Оскверненном лесу. Вонища же!$B$BНо раз это важно для наших мохнатых друзей, значит важно и для меня. Хочу проверить, водится ли эта ароматная зверушка до сих пор, хоть воды там и осквернены магией скверны. Возьмёшься?",
    "Найдите ароматную скверную рыбу в Оскверненном лесу и отнесите её Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Ароматная скверная рыба", nil, nil, nil,
    originalTitle = "Eau de Parfish"
}

RUQL_QUESTS[26108] = {
    "Неукротимый Ун'Горо",
    "Мало где в этом мире я ещё не рыбачил, но дикие воды кратера Ун'Горо — как раз одно из таких мест. Если бы эти старые кости выдержали спуск туда, я бы с радостью закинул удочку в тамошних неукротимых водах. Увы, придётся положиться на такую молодёжь, как ты.$B$BОрсооха знает толк в экзотической рыбе. Может, принесёшь нам десяток, а мы уж полакомимся, глядя на тебя?",
    "Поймайте 10 шипастых огненных рыб в кратере Ун'Горо и отнесите их Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Шипастая огненная рыба", nil, nil, nil,
    originalTitle = "Untamed Un'Goro"
}

RUQL_QUESTS[26109] = {
    "Орочье браконьерство",
    "Верные Легиону орки, что засели в крепости Фелстоун в Выжженных землях, вылавливают всю рыбу у побережья дочиста, чтобы прокормить свою ненасытную демоническую армию. Надо действовать, пока не перевелись прекрасные оранжевые груперы, что водятся у тех берегов!$B$BВыловите десяток и принесите Уифле. Она позаботится о том, чтобы они спокойно жили здесь, пока мы не разберёмся с этими орками и не выпустим рыбу обратно.",
    "Поймайте 10 оранжевых груперов в Выжженных землях и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Оранжевый групер", nil, nil, nil,
    originalTitle = "Orcs and Their Overfishing"
}

RUQL_QUESTS[26110] = {
    "Редчайшая из редких",
    "Эх, Азшара. Второй дом для меня, да и для друзей моих — родной дом. Столько тут мест для рыбалки, что всегда найдёшь для себя что-то новенькое.$B$BЯ провёл в Азшаре больше времени, чем где-либо ещё, но одна добыча всё никак мне не даётся: сапфировый гольян. Когда его ловит фурболг, рыба идёт не в котёл, а на стену — как трофей! Может, попытаешь удачи сам? Может статься где угодно...!",
    "Поймайте сапфирового гольяна в Азшаре и отнесите его Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Сапфировый гольян", nil, nil, nil,
    originalTitle = "Rarest of Them All"
}

RUQL_QUESTS[26111] = {
    "Возвращение карманных часов",
    "Ох, милок, дела мои плохи. Только вернулся из поездки к лавовым озёрам Тлеющего ущелья — и не могу найти свои счастливые карманные часы!$B$BЭтим старым костям надо бы сперва отдохнуть, прежде чем снова пускаться в путь, но если я протяну слишком долго, лава расплавит мои часы в жижу, как только магия развеется. Может, смотался бы туда да выловил их для меня? Уифла их потом почистит, если принесёшь.",
    "Найдите карманные часы Барло в Тлеющем ущелье и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Карманные часы Барло", nil, nil, nil,
    originalTitle = "Plucking a Pocketwatch"
}

RUQL_QUESTS[26112] = {
    "Тролличья форель",
    "Тролли из Андже'вата скрещивали пресноводную форель с морским окунем и вывели новый вид рыбы, что на общем языке зовётся «длинной форелью». Давненько мы её не пробовали. Может, сходишь в Танарис да посмотришь, что удастся выловить?",
    "Поймайте 10 длинных форелей в Танарисе и отнесите их Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Длинная форель", nil, nil, nil,
    originalTitle = "Troll Trout"
}

RUQL_QUESTS[26113] = {
    "Сказочная рыбалка",
    "Присядь-ка, $C, расскажу тебе одну историю.$B$BЖили-были во Внутренних землях высшие эльфы, которые вовсе не умели рыбачить. Довелось мне как-то сцепиться с тамошними троллями Витербарк — подробностей рассказывать не буду, — но в благодарность за спасение я научил эльфов рыбачить, и им так понравилось! Во всяком случае, так они говорили.$B$BПотом оказалось, что они просто меня жалели. С тех пор я туда особо не суюсь, но если тебе не в лом туда наведаться — Уифла давно мечтает о мешке золотистых окуней.",
    "Поймайте 10 золотистых окуней во Внутренних землях и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Золотистый окунь", nil, nil, nil,
    originalTitle = "Fairytale Fishing"
}

RUQL_QUESTS[26114] = {
    "Рыбалка у острова Перо Луны",
    "Остров Перо Луны — местечко довольно отдалённое для рыбалки, но клюёт там знатно, если найдёшь верное место.$B$BЕсли хочешь испытать себя против лучшего, что может предложить океан, поищи голубого марлина. Уж он задаст тебе жару, пока будешь его вытягивать, зато какое филе получится всего из одной такой рыбины! А уж с этим Орсооха тебе поможет.",
    "Поймайте голубого марлина у острова Перо Луны в Фераласе и отнесите его Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Голубой марлин", nil, nil, nil,
    originalTitle = "Feathermoon Fishing"
}

RUQL_QUESTS[26115] = {
    "Улов из мрачных вод",
    "Эгей, $C! Мои старые кости скрипят от воспоминаний о рыбалке минувших дней, и есть у меня к тебе предложение. Мутные воды Болота Печали кишат всякой скользкой живностью, которую обожает Уифла, и, думаю, самое время закинуть удочки да посмотреть, что попадётся. Но берегись — в болоте не только рыба водится. Там, в мутной глубине, таятся опасности, так что гляди в оба.",
    "Поймайте 10 гряземордых камбал в Болоте Печали и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Гряземордая камбала", nil, nil, nil,
    originalTitle = "Reeling in the Murk"
}

RUQL_QUESTS[26116] = {
    "Просеивая песок",
    "Небось думаешь, раз Бесплодные земли — значит, и рыбалка там никудышная. И был бы прав, кабы гоблины не обосновались в Спрингсокете. Оказывается, под пустыней есть вода, а в воде — рыба!$B$BЕсли ты там ещё не бывал — считай, упускаешь знатную рыбалку! Ну что, готов закинуть удочку да посмотреть, что клюнет?",
    "Поймайте 10 песчаных цедильщиков в Бесплодных землях и отнесите их Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Песчаный цедильщик", nil, nil, nil,
    originalTitle = "Sand Sifting"
}

RUQL_QUESTS[26117] = {
    "Охота на тени",
    "Слушай сюда, $C, сдаётся мне, у тебя хватит духу и хватки на одно из самых трудных дел, за какое только берётся рыбак — ловлю акул.$B$BВерно говорю: в мутных глубинах Пылевых топей акул хоть отбавляй, только и ждут, чтоб их поймали. Здоровенные, злющие — задать тебе жару они точно смогут, не скоро забудешь. Как думаешь, хватит ли у тебя духу помериться силами с зубастой пастью из глубин?",
    "Поймайте коралловую акулу в Пылевых топях и отнесите её Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Коралловая акула", nil, nil, nil,
    originalTitle = "Chasing Shadows"
}

RUQL_QUESTS[26118] = {
    "Полосы Тернистой долины",
    "Эгей, $R! Слыхал про полосатого головостоя? Рыба до того нарядная, что остальная рыба ей завидует. Я уже не такой прыткий, как раньше, да и снасти мои просят передышки, так что передаю факел тебе. Ступай да налови десяток этих скользких хитрецов в Тернистой долине. Они там как на своём подводном показе мод!$B$BА вот и подвох: как поймаешь — найди Уифлу. Покажи ей эту рыбную красоту да скажи, что это сливки водного общества Азерота. Кто знает, может, и фурболгов кой-чему в рыбалке подучим, да ещё и повеселимся на славу! Ну а теперь — ступай, и пусть полосатые головостои будут сговорчивы, как гном в кондитерской.",
    "Поймайте 10 полосатых головостоев в Тернистой долине и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Полосатый головостой", nil, nil, nil,
    originalTitle = "Stranglethorn Stripes"
}

RUQL_QUESTS[26119] = {
    "Ракушки из глубин",
    "Знаешь, $N, из тебя выйдет отменный $Gрыбак:рыбачка;, да ещё и со вкусом что надо!$B$BЕсли ищешь лучшие морепродукты — далеко ходить не надо, ступай на побережье Пустошей, там моллюсков ловят не хуже окуня. Странные они создания, эти солнечные моллюски. Уифла будет очень благодарна, если и ей принесёшь немного.",
    "Соберите 10 солнечных моллюсков в Пустошах и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Солнечный моллюск", nil, nil, nil,
    originalTitle = "Shells in the Depths"
}

RUQL_QUESTS[26120] = {
    "Зубастые воды",
    "Привет, $C. Если ищешь местечко потише да поспокойнее, загляни в Нагорье Арати — одно из немногих мест, где можно порыбачить сразу в двух океанах всего в двух шагах друг от друга!$B$BНо пусть тихие пейзажи тебя не обманывают — рыбалка там кусается, и в буквальном смысле! Берегись зубастой стромной рыбы. Ноги отхватит, если встанешь посреди косяка. К счастью, они одиночки, так что шанс не так уж велик. Принесёшь Орсоохе одну на пробу?",
    "Поймайте зубастую стромную рыбу в Нагорье Арати и отнесите её Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Зубастая стромная рыба", nil, nil, nil,
    originalTitle = "Sharp-Infested Waters"
}

RUQL_QUESTS[26121] = {
    "Дымящиеся берега",
    "Воды в Тысяче Игл немного, $C. По правде говоря, я так ни разу и не удосужился закинуть удочку в единственном известном мне месте — в парных бассейнах под Гримтотемским укреплением.$B$BЛюбопытно, что ты там найдёшь. Слыхал байку про какого-то поседевшего угря, что ушёл от одного моего приятеля. Наверное, выдумки, но разве не хочется проверить? Уифла оправит на стену всё, что бы ты ни принёс.",
    "Поймайте серебристо-парового угря в Тысяче Игл и отнесите его Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Серебристо-паровой угорь", nil, nil, nil,
    originalTitle = "Steamy Shores"
}

RUQL_QUESTS[26122] = {
    "Скитания по Болотине",
    "Немало времени я провёл когда-то в Болотине — уж очень там богатая рыбалка, любая на выбор: пруд, озеро, река, топь, море — на всё найдётся своя рыба. Столько там пропадал, что даже свою любимую блесну там позабыл.$B$BСлушай, если окажешься там — не приглядишь за ней? Орсооха отлично чинит блёсны, так что если найдёшь — он её в порядок приведёт.",
    "Найдите давно потерянную блесну в Болотине и отнесите её Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Давно потерянная блесна", nil, nil, nil,
    originalTitle = "Wetland Wanderin'"
}

RUQL_QUESTS[26123] = {
    "Мурлоки и грязевые рыбки",
    "В Предгорьях Хилсбрада мурлоков — не счесть, вдоль всего южного побережья. Рыбача как-то в Южнобережье, я приметил одну занятную грязевую рыбку, что любит крутиться рядом с мурлоками — авось перепадёт объедок-другой от их трапезы. Знатная это еда, такие грязевые рыбки, а наши запасы совсем оскудели.$B$BКонечно, грязевых мурлят и в других местах Хилсбрада сыщешь, но вот что я знаю про них. Ну как, возьмёшься размотать удочку да принести нам пир на славу?",
    "Поймайте 10 грязевых мурлят в Предгорьях Хилсбрада и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Грязевой мурлёнок", nil, nil, nil,
    originalTitle = "Murloc Mudkips"
}

RUQL_QUESTS[26124] = {
    "Прекрасные воды",
    "Живописная красота Ясеневого леса — тихая гавань для всех, кто ищет покоя вдали от суеты мира. А посреди этого спокойствия — богатый улов, только и жди, когда его выловят. Реки и озёра Ясеневого леса кишат жизнью, самое время закинуть удочку и урвать свой кусочек природных даров.$B$BГоворю про гордость ночных эльфов — быстрохвостого лунного гольяна, любимца Орсоохи! Ничто не сравнится с косяком лунных гольянов, что мелькают под водой у твоего насеста в свете полной луны, уж поверь. Буду благодарен, если наловишь для нас.",
    "Поймайте 10 быстрохвостых гольянов в Ясеневом лесу и отнесите их Орсоохе в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Быстрохвостый лунный гольян", nil, nil, nil,
    originalTitle = "Beautiful Waters"
}

RUQL_QUESTS[26125] = {
    "Суп из каменной рыбы",
    "Привет, $C, если ищешь минутку покоя среди суровых пиков и петляющих ущелий Когтистых гор, у меня как раз есть для тебя средство. Уифла давно хочет опробовать новый рецепт супа из каменной рыбы, а для него нужен главный ингредиент — каменнокожие гольяны, что водятся только в Когтистых горах. Чешуя у них крепче гвоздей, зато в вареве они разойдутся в самый раз, вместе с хлыстовым корнем да успокаивающими травами.$B$BНе против сходить туда да принести нам знатный улов?",
    "Поймайте 10 каменнокожих гольянов в Когтистых горах и отнесите их Уифле в деревню Чернопасть в Азшаре.",
    nil, nil,
    "Каменнокожий гольян", nil, nil, nil,
    originalTitle = "Stonefish Soup"
}

RUQL_QUESTS[26126] = {
    "Угри Спрингсокета",
    "Веришь ли, нет ли, а рыбалка в Спрингсокете весьма бойкая! Хоть я пока единственный, кто и правда этим увлекается, не сомневаюсь — со временем найдутся и другие. В общем, есть у меня для тебя задачка, если готов взяться.$B$BЭтот пруд питается водой из подземной пещерной системы глубоко внизу. Рыба там слепая и порой всплывает наверх, находя дорогу на поверхность. Мне доводилось поймать лишь пару штук то тут, то там, но вкуснее рыбы я в жизни не пробовал!$B$BПопробуй порыбачить, вдруг поймаешь несколько штук. Если повезёт — принеси их мне, и я покажу, как их готовить.",
    "Принесите 10 сырых угрей Спрингсокета Зимо в Спрингсокете.",
    nil, nil,
    "Сырой угорь Спрингсокета", nil, nil, nil,
    originalTitle = "Springsocket Eels"
}

