-- Project Epoch: пакет переведён по базе pfQuest-epoch 2026-09-06.
-- Внутренние земли / Пик Аэри, клан Крепкого Молота (ID 26167-26196).
-- Содержит настоящие цепочки по pre/next: "Falling Up To Grace" (26171-26176),
-- "Snapjaw"/Убо-отшельник (26179-26184), совозвери/Риррек (26191-26194).
-- Многие start/end NPC не резолвятся через pfQuest-epoch (это стоковые
-- WotLK-юниты, которых нет в epoch-таблице unit-ов) — имена взяты из текста
-- квестов (O/D), где они называются напрямую.
RUQL_QUESTS[26167] = {
    "Липкая ситуация",
    "У меня для тебя есть работёнка, и если ты, как и я, ценишь доброе пенное, тебе понравится это задание.$B$BПенное! Это напиток, балда.$B$BКакой бы выбор у нас тут ни был, ребятам и девчатам всегда охота чего-то... особенного, с изюминкой. На заброшенном форпосте Орды завалялся запас «Медовой зыби» Внутренних земель — ещё с тех времён, когда они там торговали. Такого доброго пенного нынче не сыщешь! Бутылки можно найти в ящиках у Крадущейся скалы.$B$BЗадачка не из лёгких: в руинах кишат мерзкие слизни и слизи, а по слухам, верховодит там какой-то слизень-переросток. Как бы то ни было — добудь пенное и возвращайся ко мне.",
    "Найдите 10 бутылок «Медовой зыби» Внутренних земель в ящиках рядом с заброшенной базой Орды у Крадущейся скалы.",
    nil, nil,
    "«Медовая зыбь» Внутренних земель", nil, nil, nil,
    originalTitle = "A Sticky Situation"
}

RUQL_QUESTS[26168] = {
    "Нельзя приготовить омлет, не разбив...",
    "Уизербарки к юго-востоку отсюда присматривают за яйцами выводка Шадры. Даже если мы перебьём самих уизербарков, эти яйца всё равно останутся лежать, дожидаясь часа, чтобы вылупиться и выпустить этих жутких тварей в дикие земли.$B$BНадо разобраться с этой угрозой как следует. Вырви все яйца, что найдёшь, из кладок и принеси их мне. Не пытайся уничтожить их сам — рискуешь выпустить малышей наружу.$B$BКогда принесёшь их сюда, я прослежу, чтобы их правильно утилизировали!",
    "Соберите 12 яиц отродья Шадры в Шадра'Алор и вернитесь к Керру Зоркому в Пик Аэри.",
