RUQL_QUESTS[26170] = {
    "Очистить берег",
    "Эй, мон, рыбные воды у деревни редеют всё больше и больше, и я знаю, почему: те треклятые солёные пловцы прибрежья. Мне нужен смельчак, чтобы сделать для меня одну простую вещь... извести их как можно больше. Справишься?",
