RUQL_QUESTS[26171] = {
    "Взлёт вместо падения",
    "Меня прислал сюда сам Верховный Механик — укреплять отношения между Альянсом и кланом Крепкого Молота. Моя задача проста: сделать полёты на грифонах безопаснее.$B$BЯ собираюсь смастерить парашюты, которые будут чувствовать падение наездника и раскрываться автоматически. Звучит неплохо, правда?$B$BНо чтобы их сделать, мне нужны материалы, которых у Крепкого Молота попросту нет. Начнём с самого парашюта. Уизербарки неподалёку неплохо разбираются в ткачестве, а их пауки, при всей своей мерзости, дают прекрасную нить. Раздобудь мне немного, и я примусь за парашюты.",
    "Соберите 8 лоскутов шали уизербарков и 8 отрезов безупречного шёлка стражей кладки у уизербарков в Шадра'Алор.",
