RUQL_QUESTS[26175] = {
    "Взлёт вместо падения",
    "Вот и всё... пора показать, на что это способно! Отнеси это самому Фалстаду, чтобы он мог увидеть всё вблизи, и дёрни за шнур этого ранца.$B$BНе успеешь оглянуться, как взлетишь высоко в небо, а как только начнёшь падать — раскроется парашют. Я почти уверена... что ж, есть только один способ проверить!",
    "Используйте реактивный ранец Тиззи, чтобы взлететь высоко в небо, и испытайте автоматически раскрывающийся парашют.",
    nil, nil,
    "Испытать реактивный ранец Тиззи.",
    originalTitle = "Falling Up To Grace"
}

RUQL_QUESTS[26176] = {
    "Взлёт вместо падения",
    "Если это не расположит к нам Крепкий Молот, то я уж и не знаю, что расположит. Не окажешь мне честь — передашь это Фалстаду?",
    "Доставьте альтоматический парашютный набор Фалстаду Крепкому Молоту.",
    nil, nil,
    "Доставить альтоматический парашютный набор Фалстаду Крепкому Молоту.",
    originalTitle = "Falling Up To Grace"
