RUQL_QUESTS[26177] = {
    "Друзья остроклювов",
    "Наш клан почитает грифонов как священных животных. Это величавые создания небес, куда больше, чем просто бессловесные звери — они умны и хитры. Кто-то говорит, что мы держим их как лошадей, но на деле это скорее дружба.$B$BЕсли хочешь подружиться с Крепким Молотом — сперва подружись с нашими грифонами! Их любимое лакомство редкое: смесь хрустящего тростника и свежих рыбных стейков. Эти негодники от него без ума.$B$BЧтобы приготовить угощение, тебе нужно собрать материалы. К востоку отсюда найдёшь большой ручей, впадающий в реку, что течёт вдоль побережья, начинаясь у Агол'Ваты. Там ты найдёшь мясистых груперов и королевский хрустящий тростник. Принеси их мне, и мы приготовим свежую порцию.",
    "Соберите 8 стейков групера и 12 стеблей королевского хрустящего тростника для лакомства грифонам.",
    nil, nil,
    "Стейк групера", "Королевский хрустящий тростник", nil, nil,
    originalTitle = "Razorbeak Friends"
}

RUQL_QUESTS[26178] = {
    "Друзья остроклювов",
    "Возьми этот мешок с угощением. Он свежий, с пылу с жару. Наши прирученные остроклювы бродят по лесам к юго-востоку от вольера. Ступай покорми парочку, будь добр.",
    "Скормите лакомство для грифонов прирученным остроклювам к юго-востоку от Пика Аэри.",
