RUQL_QUESTS[26179] = {
    "Отшельник Внутренних земель",
    "У нас беда, нужен кто-то сильный вроде тебя, чтобы её решить.$B$BОдин из наших стражей, Убо-отшельник, ушёл из деревни, потому как не любит черепашье мясо. Теперь живёт один, к северу отсюда.$B$BМы скучаем по Убо и его умению охранять. Хотим, чтобы он вернулся в деревню. Найди его, приведи назад — щедро тебя наградим. Сделаешь это для нас, мон?",
    "Найдите Убо-отшельника, бывшего стража деревни Реванантаск, который ушёл, разозлившись на то, что в деревне едят черепашье мясо.",
    nil, nil,
    "Найти Убо-отшельника.",
    originalTitle = "Hinterlands Hermit"
}

RUQL_QUESTS[26180] = {
    "Угощение для щелкунов",
    "Если и правда существует лоа, что принимает облик черепахи, то это, должно быть, очень особенные создания. Я не зандалари, да и матушка моя не была — но я любил слушать её байки о лоа, которым поклоняются все тролли.$B$BПлемя Реванантаска поедает уйму черепашьего мяса, порой убивая их просто ради развлечения. Меня от этого тошнит.$B$BХочу поднести этим черепахам дар, который порадовал бы даже Торгу. Я видел, они едят особый тростник и рыбу, которую иногда сносит течением с реки выше по побережью. Не соберёшь ли для меня немного того и другого, а заодно стейков из той рыбы, чтобы я приготовил им вкусное угощение.",
    "Соберите 8 стейков групера и 12 стеблей королевского хрустящего тростника для угощения щелкунам.",
    nil, nil,
    "Стейк групера", "Королевский хрустящий тростник", nil, nil,
    originalTitle = "Snapjaw Snacks"
}

RUQL_QUESTS[26181] = {
    "Раздача угощений",
    "Из того, что ты принёс, я приготовил особое угощение для щелкунов. Сделай одолжение — раздай его черепахам-щелкунам вдоль всего побережья.",
    "Скормите угощения черепахам-щелкунам вдоль побережья Внутренних земель.",
    nil, nil,
    "Скормить угощения черепахам-щелкунам вдоль побережья Внутренних земель.",
    originalTitle = "Snack Distribution"
}

RUQL_QUESTS[26182] = {
    "Мирное подношение",
    "Теперь понимаешь, почему я так люблю этих черепах и почему не вернусь в деревню? Устал уже, что они шлют ко мне таких искателей приключений, как ты, чтобы уговорить меня вернуться. У меня есть отличная весточка для них, которая, думаю, положит этому конец.$B$BУ угощений, что ты раздал, есть побочный эффект — они быстро проходят сквозь черепах, а значит, у нас будет вдоволь «орешков», чтобы красиво их упаковать для Реванантаска.$B$BСобери немного для меня и возвращайся поскорее, пока они ещё свежие.",
    "Соберите 8 «орешков» черепах вдоль побережья Внутренних земель.",
    nil, nil,
    "«Орешек» черепахи", nil, nil, nil,
    originalTitle = "An Offering Of Peace"
}

RUQL_QUESTS[26183] = {
    "Мирное подношение",
    "Следующий шаг для нас — раздобыть красивую нарядную шкатулку, чтобы они подумали, что это и правда славный подарок. Хотя, если подумать, стоило бы сперва отправить тебя за шкатулкой, чтобы руки твои поменьше пачкались в «орешках»... ну да ладно!$B$BК северу отсюда — небольшой остров, где я упокоил прах матушки в нарядном ларце после её смерти. Это чудесная вещица ручной работы, так что подойдёт для нашего плана как нельзя лучше, а самое главное — матушка моя нашла бы всю эту историю уморительной.",
    "Найдите резной ларец Убо на острове к северу от его хижины.",
    nil, nil,
    "Резной ларец Убо", nil, nil, nil,
    originalTitle = "An Offering Of Peace"
}

RUQL_QUESTS[26184] = {
    "Мирное подношение",
    "Отнеси этот «мирный дар» дозорному Оуи обратно в деревню — думаю, тогда он наконец перестанет присылать ко мне таких искателей приключений, как ты.$B$BСтупай — и пусть уж лучше ты будешь последним.",
    "Отнесите мирный дар Убо дозорному Оуи в деревню Реванантаск во Внутренних землях.",
