RUQL_QUESTS[26185] = {
    "Потерянные бусы Ларда",
    "Иногда Лард любит бродить к причалу и кидать камешки в море. Лард даже один раз пустил «блинчик» три раза подряд!$B$BЛард так разволновался, что зашвырнул бусы в воду... и тут — Лард видит, как проплывает злюка-акула Болтозуб и глотает бусы целиком! Не достанешь их из брюха Болтозуба для Ларда?",
    "Добудьте бусы Ларда у акулы Болтозуба, которая часто патрулирует побережье Внутренних земель.",
    nil, nil,
    "Бусы Ларда", nil, nil, nil,
    originalTitle = "Lard's Lost Beads"
}

RUQL_QUESTS[26186] = {
    "Детали издалека",
    "Чистый ад — обслуживать осадные машины так далеко от Стальгорна. Мы официально не часть Альянса, так что доступа к новейшим деталям у нас нет.$B$BМог бы попросить того дипломата снаружи о помощи, но если он согласится, увязнем в бюрократии и прочей ерунде. Моя жена придумала способ попроще, чтобы получить прямую поставку: еда! Перед ней слаб любой дворф.$B$BОтнеси эту корзину угощений Миолору Расколотая Ярость в Стальгорн, а взамен привези мне детали.",
    "Отнесите корзину угощений Миолору Расколотая Ярость в Стальгорн в обмен на детали для осадных машин.",
    nil, nil,
    "Отнести корзину угощений Миолору Расколотая Ярость в Стальгорн.",
    originalTitle = "Parts From Afar"
}

RUQL_QUESTS[26187] = {
    "Детали издалека",
    "Обычно я бы не позволил никаким деталям покинуть оборону Стальгорна, но учитывая, что ты мне принёс... что ж... так и быть, сделаем исключение. Не терпится приступить. Отнеси эти детали Крепкому Молоту, и будем считать, что мы в расчёте.$B$BВ следующий раз пусть ещё эля подкинут!",
    "Верните ящик с деталями для осадных машин главному инженеру Урулу в Пик Аэри.",
    nil, nil,
    "Вернуть ящик с деталями для осадных машин главному инженеру Урулу в Пик Аэри.",
    originalTitle = "Parts From Afar"
}

RUQL_QUESTS[26188] = {
    "Ловчие на ловчих",
    "Немало храбрых дворфов сгинуло в суровых диких землях Внутренних земель, $R. Волки Серебряной Гривы — одна из самых больших угроз для наших охотников. Они таятся в засаде, прячась среди кустов и складок местности, а затем бросаются в атаку, стоит подвернуться случаю.$B$BТакую свирепость нельзя оставлять безнаказанной!$B$BЧтобы найти Серебряную Гриву, нужно мыслить как Серебряная Грива. Выследи ловчих и воющих! Перебей их всех!",
    "Мастер грифонов Коготь-Топор в Пике Аэри просит вас убить 15 скрытных волков Серебряной Гривы и 15 воющих волков Серебряной Гривы. Вернитесь к нему, когда задание будет выполнено. Коготь-Топор упомянул, что волки прячутся в диких землях Внутренних земель.",
    nil, nil,
    "Скрытный волк Серебряной Гривы", "Воющий волк Серебряной Гривы", nil, nil,
    originalTitle = "Stalking the Stalkers"
}

RUQL_QUESTS[26189] = {
    "Отменная слизь",
    "Немногие дворфы об этом знают, но чтобы придать моему пойлу НАСТОЯЩИЙ кураж, я подмешиваю в него чуток здешней слизи. Ага, той самой — гигантской зелёной слизи, что жрёт дворфов почём зря.$B$BНо для такого пойла нужен кураж что надо, значит, нужна слизь погуще! Внизу, у Крадущейся скалы, обитает одна такая — мать всех слизней, огромная-преогромная... мы зовём её Дайрглоб.$B$BЕсли духу хватит — спустись туда и отхвати для меня кусок Дайрглоба!",
    "Добудьте образец Дайрглоба у Дайрглоба.",
    nil, nil,
    "Образец Дайрглоба", nil, nil, nil,
    originalTitle = "Prime Slime"
}

RUQL_QUESTS[26190] = {
    "Отменная слизь",
    "Интересуешься исследованием склизких слизней? Слизни Крадущейся скалы — дело нешуточное. Сколько бы мы их ни зачищали, они вечно возвращаются, будто регенерируют, точно тролли... или что-то вроде того.$B$BЗнаешь, что я думаю? Думаю, там внизу есть какой-то источник, что штампует слизней одного за другим. Хочу выяснить, что это такое! Так что вперёд, искатель приключений, спустись в Крадущуюся скалу и принеси мне образец того, что бы там ни порождало всю эту слизь. Вот уж будет чем заняться в исследованиях!",
    "Добудьте образец Дайрглоба у Дайрглоба.",
    nil, nil,
    "Образец Дайрглоба", nil, nil, nil,
    originalTitle = "Prime Slime"
}

RUQL_QUESTS[26191] = {
    "Свирепое ремесло",
    "Наша давняя вражда с местными троллями порой затихает до мирного противостояния — но мир никогда не длится долго.$B$BВо Внутренних землях совозвери спутывают все карты. То и дело они уничтожают отряд троллей или разоряют обоз снабжения Крепкого Молота, и взаимные обвинения перерастают в настоящий бой.$B$BЕсли хотим хоть какого-то мира — нужно разобраться с этими совозверьми. Ступай на восток и сократи их число, тогда страсти улягутся.",
    "Убейте 10 свирепых совозверей к востоку от Пика Аэри.",
    nil, nil,
    "Свирепый совозверь", nil, nil, nil,
    originalTitle = "A Vicious Vocation"
}

RUQL_QUESTS[26192] = {
    "Первобытная взбучка",
    "Чем дальше на восток, тем более первобытными и крепкими становятся совозвери. Задача сократить их число будет только труднее, но ради Крепкого Молота мы должны это сделать.$B$BОтправляйся в самое сердце Внутренних земель и сократи число совозверей. С каждым убитым зверем Внутренние земли становятся чуть спокойнее.",
    "Найдите и истребите 10 первобытных совозверей в центральных областях Внутренних земель.",
    nil, nil,
    "Первобытный совозверь", nil, nil, nil,
    originalTitle = "Primitive Pummeling"
}

RUQL_QUESTS[26193] = {
    "Дикий натиск",
    "Совозвери ближе всего к деревне Реванантаск, на побережье, причиняют больше всего вреда. Слышал, недавно они убили патруль реванантасков, но когда тролли нашли тела своих погибших товарищей, вину возложили на нас. Больно просить тебя об этом, но этим совозверям нельзя позволить и дальше раздувать напряжение между дворфами и троллями.$B$BДикие совозвери сильнее и, похоже, куда горячее нравом — так что будь осторожен... но покончить с ними придётся.",
    "Найдите диких совозверей далеко на востоке, у Дозорных утёсов, и убейте 10 из них.",
    nil, nil,
    "Дикий совозверь", nil, nil, nil,
    originalTitle = "Savage Slam"
}

RUQL_QUESTS[26194] = {
    "Вожак совиного племени",
    "Раз уж их число в округе сократилось, пора взяться за их «вожака». Их вождь — просто самый большой и злой совозверь в округе. Остальные его то ли боятся, то ли уважают... сам не знаю, что из двух.$B$BЗовут его Риррек, и найти его можно далеко на востоке отсюда, к северу от Джинта'Алора. По словам наших разведчиков, зверь этот очень скрытный, но умнее прочих. Его видели за постройкой чучел там, где он живёт. Чтобы выманить его, подожги одно — готов поспорить, он выйдет из укрытия.",
    "Найдите чучело Риррека и подожгите его, чтобы выманить зверя. Когда он появится, убейте его.",
    nil, nil,
    "Сжечь чучело Риррека.",
    originalTitle = "Owlkin Leadership"
}

RUQL_QUESTS[26195] = {
    "Вожак совиного племени",
    "Раз уж их число в округе сократилось, пора взяться за их «вожака». Их вождь — просто самый большой и злой совозверь в округе. Остальные его то ли боятся, то ли уважают... сам не знаю, что из двух.$B$BЗовут его Риррек, и найти его можно далеко на востоке отсюда, к северу от Джинта'Алора. По словам наших разведчиков, зверь этот очень скрытный, но умнее прочих. Его видели за постройкой чучел там, где он живёт. Чтобы выманить его, подожги одно — готов поспорить, он выйдет из укрытия.",
