    "Первым делом крепкий дворф из клана Крепкого Молота после долгого дня просит доброго эля и чего-нибудь поесть. А лучшая еда в наших краях — вкуснейшая черепашья похлёбка.$B$BБеда в том, что Пик Аэри — едва ли не самое дальнее место от гигантских черепах во всех Внутренних землях. Ступай к Дозорным утёсам и настреляй немного черепах для меня — принеси их постное филе!",
