RUQL_QUESTS[26198] = {
    "Розыск: Мрачный Гребень",
    "Несколько месяцев назад, во время обычного патрулирования небес, отважного дворфа клана Крепкого Молота сбил залп троллиных копий. Его верный грифон Мрачный Гребень тяжело это пережил. С тех пор Мрачный Гребень изливает ярость на всё, что встречает: диких зверей, троллей и дворфов без разбора. Бедное животное придётся усыпить. Принесите доказательство гибели Мрачного Гребня Мастерам грифонов Пика Аэри.",
    "Найдите Мрачного Гребня, что патрулирует у озера Доблестного Ветра, и избавьте его от мучений.",
    nil, nil,
    "Найти Мрачного Гребня и избавить его от мучений.",
    originalTitle = "Wanted: Foulcrest"
}

RUQL_QUESTS[26199] = {
    "Розыск: Мрачный Гребень",
    "Пару месяцев назад один из дворфов Крепкого Молота свалился с неба от залпа наших копий. Его грифон Мрачный Гребень тяжело это перенёс. С тех пор он впадает в кровавую ярость и убивает всё подряд: диких зверей, троллей и дворфов. Принеси доказательство его гибели дозорному Оуи в деревню Реванантаск.",
    "Найдите Мрачного Гребня, что патрулирует у озера Доблестного Ветра, и убейте его.",
    nil, nil,
    "Убить Мрачного Гребня.",
    originalTitle = "Wanted: Foulcrest"
}

-- Project Epoch: пакет переведён по базе pfQuest-epoch 2026-09-06.
-- Аубердин / Темные берега (ID 26200-26208) — хаб часовой Глинды Наль'Ши.
RUQL_QUESTS[26200] = {
    "Равновесие леса",
    "Ишну-ала, $N. Во всём сущем есть равновесие, и Элуна хранит лес, чтобы оно сохранялось. В последнее время это равновесие сдвигается, и я боюсь, если ничего не предпринять, это может пошатнуть сами основы Азерота. Мы молились Элуне, чтобы она послала кого-то на помощь, и вот пришёл ты.$B$BСейчас главный источник этого нарушения — колония друидов-сов к востоку. Мне доносили, что нечто похожее происходило на Тельдрассиле, где мирная колония совиного народа обратилась в буйный хаос. Друиды-совы нападают на всё, что видят, и нарушают течение природы. Прошу, разберись с колонией и верни лесу равновесие.",
    "Убейте 5 молодых друидов-сов и 10 друидов-сов и вернитесь к часовой Глинде Наль'Ши в Аубердин.",
    nil, nil,
    "Молодой друид-сова", "Друид-сова", nil, nil,
    originalTitle = "Balancing the Forest"
}

RUQL_QUESTS[26201] = {
    "Равновесие леса",
    "К сожалению, похоже, что мы очистили лишь малую часть колонии. Старшие друиды-совы обитают дальше на востоке леса. Мне горько уничтожать этих диких созданий, но нужно делать то, что необходимо.$B$BВернись в колонию друидов-сов и поищи дальше. Нужно полностью устранить угрозу, чтобы Аубердин оставался в безопасности, а равновесие было восстановлено.",
    "Убейте 3 оракулов-сов и 10 неистовых друидов-сов, затем вернитесь к часовой Глинде Наль'Ши в Аубердин.",
    nil, nil,
    "Оракул-сова", "Неистовый друид-сова", nil, nil,
    originalTitle = "Balancing the Forest"
}

RUQL_QUESTS[26202] = {
    "Молот Сумерек",
    "Аубердину грозит серьёзная опасность, $N. Они называют себя Молотом Сумерек. Это культ, что сеет хаос и раздор, нарушая равновесие леса. Они поклоняются Древним богам и жаждут пробудить их, желая гибели всему Азероту.$B$BИх нужно остановить! У них есть форпост у Клинка Владыки, далеко на юге, у самой границы с Ясеневым лесом. Ступай, $N, и очисти Темные берега от скверны этого культа.",
    "Убейте 8 громил Сумерек и 8 адептов Сумерек и вернитесь к Аланндариан Ночной Песне в Аубердин.",
    nil, nil,
    "Громила Сумерек", "Адепт Сумерек", nil, nil,
    originalTitle = "The Twilight's Hammer"
}

RUQL_QUESTS[26203] = {
    "Добро пожаловать в Аубердин",
    "Добро пожаловать в Аубердин, надеюсь, дорога прошла гладко. Здесь ещё многое предстоит сделать, и мы были бы очень признательны за твою помощь. Друиды-совы, фурболги, мурлоки, культисты, наги... список смутьянов длинный!$B$BДумаю, лучше всего будет познакомиться с квартирмейстером Ньяной. Она в ратуше, разбирает донесения и следит за разными делами, что у нас творятся. С нетерпением жду новой встречи с тобой, и да благословит тебя Элуна.",
    "Явитесь к квартирмейстеру Ньяне в Аубердине.",
    nil, nil,
    "Явиться к квартирмейстеру Ньяне в Аубердине.",
    originalTitle = "Welcome to Auberdine"
}

RUQL_QUESTS[26204] = {
    "Угроза Серой Пелены",
    "Раньше я жил в Западном Крае, но бросил свой участок у карьера Золотого Побережья, когда неподалёку от берега развелись мурлоки. Я добрался аж до Темных берегов, надеясь выбросить память об этих чешуйчатых тварях из головы. Но всё без толку, $C! Мурлоков полно и здесь, на побережье прямо к югу от города!$B$BЕсли в тебе есть хоть капля сострадания, прошу, покончи с ними, прежде чем они разрастутся в угрозу, что нас захлестнёт. Их вопли мне снятся в кошмарах....",
    "Убейте мурлоков Серой Пелены к югу от Аубердина для Билла Вилэнда.",
    nil, nil,
    "Мурлок Серой Пелены", nil, nil, nil,
    originalTitle = "The Greymist Menace"
}

RUQL_QUESTS[26205] = {
    "Угроза Серой Пелены",
    "Не могу спать спокойно, пока эта угроза висит над нами, $C, так что я прошёлся дальше на юг вдоль побережья. Представляешь, там, на самом дальнем юге Темных берегов, мурлоки ещё крепче!$B$BОткуда-то они всё прибывают. Пойду разберусь, откуда, пока ты кладёшь конец их угрозе.$B$BТы ведь позаботишься об этом, правда?",
    "Убейте мурлоков Серой Пелены вдоль южного побережья Темных берегов для Билла Вилэнда в Аубердине.",
    nil, nil,
    "Мурлок Серой Пелены", nil, nil, nil,
    originalTitle = "The Greymist Menace"
}

RUQL_QUESTS[26206] = {
    "Мелкобород",
    "У мурлоков Западного Края, возможно, был вожак — не задержался достаточно, чтобы выяснить. А вот у мурлоков Темных берегов он точно есть.$B$BИди вдоль побережья на юг, почти до самого Ясеневого леса, и увидишь молодого морского великана. Вот кто стоит за этим нашествием мурлоков! Его нужно уничтожить, или нас захлестнёт его склизкая армия!",
    "Убейте Мелкоборода и вернитесь к Биллу Вилэнду в Аубердин.",
    nil, nil,
    "Убить Мелкоборода.",
    originalTitle = "Shoalbeard"
}

RUQL_QUESTS[26207] = {
    "Розыск: Туманный Плавник",
    "Внимание!$B$BОбъявлена награда за смерть трешадона по имени «Туманный Плавник». Это существо нападало на рыбацкие лодки в округе и стало причиной гибели по меньшей мере двух рыбаков.$B$BИзвестно, что Туманный Плавник обитает на краю глубоких вод к востоку от руин Амет'арана. За наградой обращайтесь к часовой Глинде Наль'Ши в Аубердине.$B$BСовет деревни Аубердин.",
    "Найдите и убейте трешадона по имени Туманный Плавник глубоко в море, к востоку от руин Амет'арана. Получите награду у часовой Глинды Наль'Ши в Аубердине.",
    nil, nil,
    "Убить Туманного Плавника.",
    originalTitle = "Wanted: Mistfin"
}

RUQL_QUESTS[26208] = {
    "Розыск: Сивоклык",
    "Внимание!$B$BОбъявлена награда за смерть медведя по имени «Сивоклык». Фурболги Черной Чащи заманили ясеневолесного медведя в Логово Черной Чащи, к югу, у самой границы с Ясеневым лесом. Нужно убить этого молодого медведя, пока он не превратился в чудовище под властью Черной Чащи.$B$BЗа наградой обращайтесь к часовой Глинде Наль'Ши в Аубердине.$B$BСовет деревни Аубердин.",
    "Найдите и убейте медведя по имени \"Сивоклык\". Получите награду у часовой Глинды Наль'Ши в Аубердине.",
