RUQL_QUESTS[26209] = {
    "Кости Крепкого Молота",
    "Тролли Дурной Ветви из Джинта'Алора издавна проводят мерзкие ритуалы, используя дворфийские кости, украденные с нашего кладбища. Кости они крадут по указу порочной жрицы Хексс.$B$BОтправляйся в Джинта'Алор и верни кости наших почтенных предков. Ты найдёшь их в местах силы троллей по всему городу.",
    "Соберите 10 костей воинов Крепкого Молота в Джинта'Алоре. Вернитесь к Фалстаду Крепкому Молоту в Пик Аэри, когда задание будет выполнено.",
    nil, nil,
    "Кости воинов Крепкого Молота", nil, nil, nil,
    originalTitle = "Wildhammer Bones"
}

RUQL_QUESTS[26210] = {
    "Вакансия: капитан стражи Пика Аэри",
    "Клан Крепкого Молота набирает сильных бойцов, готовых возглавить отряд для похода на троллиный город Джинта'Алор. Претенденты должны выполнить следующие задачи:$B$BИстребить воинов Дурной Ветви$B$BИстребить сумеречных колдунов Дурной Ветви$B$BИстребить живодёров Дурной Ветви$B$BИстребить стражей Аман'заси",
    "Отправляйтесь в Джинта'Алор и убейте 20 воинов Дурной Ветви, 20 сумеречных колдунов Дурной Ветви, 20 живодёров Дурной Ветви и 20 стражей Аман'заси. Выполнив задание, поговорите с Калой Хаммерфлайт в Пике Аэри во Внутренних землях.",
    nil, nil,
    "Воин Дурной Ветви", "Сумеречный колдун Дурной Ветви", "Живодёр Дурной Ветви", "Страж Аман'заси",
    originalTitle = "Job Opening: Guard Captain of Aerie Peak"
}

RUQL_QUESTS[26211] = {
    "Точечный удар",
    "Долго клан Крепкого Молота жил во Внутренних землях, и долго мы враждовали с троллями Дурной Ветви. Тролли отстроили огромный город к юго-востоку отсюда, называемый Джинта'Алор. Нам не под силу выбить их из этого оплота власти, но мы можем нанести удар, что оставит их в смятении и не даст напасть на нас.$B$BПроникни в Джинта'Алор и убей их вождей: порочную жрицу Хексс и Хита'йю Хранительницу! Полагаю, ты найдёшь их на самой вершине города.",
    "Проникните в Джинта'Алор и убейте порочную жрицу Хексс и Хита'йю Хранительницу.",
    nil, nil,
    "Порочная жрица Хексс", "Хита'йя Хранительница", nil, nil,
    originalTitle = "Tactical Strike"
}

RUQL_QUESTS[26212] = {
    "Вуду, которым они занимаются",
    "Как и многие в деревне, я не раз сталкивался с троллями Дурной Ветви и всегда восхищался качеством их оружия. Полагаю, Дурная Ветвь использует магию, чтобы усиливать дерево и сталь, — особый флюс, который они применяют при ковке и изготовлении оружия.$B$BМне бы пригодилось несколько образцов этого флюса, если ты готов отправиться в Джинта'Алор и раздобыть немного.",
    "Соберите 8 порций вудуистского флюса у троллей в Джинта'Алоре для Калы Хаммерфлайт в Пике Аэри во Внутренних землях.",
    nil, nil,
    "Вудуистский флюс", nil, nil, nil,
    originalTitle = "The Voodoo They Do"
}

RUQL_QUESTS[26213] = {
    "Любимое рыбное место Хоуина",
    "$R, ты выглядишь толковым. Можно попросить тебя об услуге?$B$BЯ рыбачил на любимом месте у вершины водопада Дозорных утёсов, далеко на востоке, когда на меня напал отряд бродячих троллей Дурной Ветви. Я бежал, спасая жизнь, и бросил все свои рыболовные снасти.$B$BНе сходишь ли к водопаду Дозорных утёсов и не соберёшь ли их для меня? Если не найдёшь всё — не беда, мне ведь на самом деле нужна только моя любимая блесна.",
    "Найдите любимую блесну Хоуина на его любимом рыбном месте у вершины водопада вдоль Дозорных утёсов, далеко к востоку от Пика Аэри.",
    nil, nil,
    "Любимая блесна Хоуина", nil, nil, nil,
    originalTitle = "Howin's Favorite Fishing Hole"
}

RUQL_QUESTS[26214] = {
    "Любимое рыбное место Хоуина",
    "Тщательно обыскав местность вокруг рыбацкого кресла, ты не находишь ни следа блесны Хоуина — ни какого-либо другого рыболовного снаряжения. Похоже, остальные вещи могло смыть водопадом. Если повезёт, они лежат в иле у подножия водопада.",
    "Найдите любимую блесну Хоуина у подножия водопада Дозорных утёсов.",
    nil, nil,
    "Найти блесну Хоуина у подножия водопада.",
    originalTitle = "Howin's Favorite Fishing Hole"
}

RUQL_QUESTS[26215] = {
    "Любимое рыбное место Хоуина",
    "Сильное течение уносит воду от водопада прочь, в Заповедное море на востоке.$B$BЕсли вещи из рыболовного ящика Хоуина подхватило течением, их вполне могло вынести на шельф океана к востоку отсюда.$B$BСтоит поискать, прежде чем возвращаться к Хоуину с вестью о том, что блесна потеряна.",
    "Найдите любимую блесну Хоуина в Заповедном море.",
