RUQL_QUESTS[26216] = {
    "Любимое рыбное место Хоуина",
    "Настоящее маленькое чудо! Рыболовная блесна зацепилась за кусок плавника прямо здесь. Ты аккуратно отцепляешь её, надеясь, что это та самая блесна, которую искал Хоуин.",
    "Вернитесь в Пик Аэри с любимой блесной Хоуина.",
