RUQL_QUESTS[26217] = {
    "Потерянное в озере",
    "После предательства Артаса в Лордероне в городе началась массовая паника. Моя семья и я были среди многих, кто бежал на лодках через озеро Лордамер.$B$BМне повезло меньше, чем остальным в моей семье — я отчалил на паре дырявых лодок, которые перевернулись недалеко от причалов к востоку от Склепа. Последнее, что я помню из своей смертной жизни — холодная рука, холоднее самой воды, что вытащила меня на берег....$B$BТак или иначе, семейные реликвии моей семьи затонули на дне озера, где и покоятся по сей день. Я бы охотно заплатил за твои услуги, чтобы вернуть эти вещи.",
    "Достаньте семейные реликвии рода Йенс со дна озера Лордамер.",
    nil, nil,
    "Отсыревший меч", "Потускневшие браслеты", nil, nil,
    originalTitle = "Lost in the Lake"
}

RUQL_QUESTS[26218] = {
    "Крушение «Кестрела»",
    "Несколько месяцев назад я разместил крупный заказ на ремесленные материалы у «Пастбищ Дымного Леса». Груз везли из Калимдора на судне под названием «Кестрел». К несчастью, корабль сел на мель в густом тумане у побережья к северу от Склепа.$B$BЯ не решался осмотреть обломки — в лесах у Лощины Северного Прилива, где корабль выброшен на берег, обитают враждебные ворген. Если бы ты смог достать для меня ящик с грузом из трюма «Кестрела», я был бы рад поделиться частью припасов внутри.",
    "Обыщите обломки «Кестрела» в Лощине Северного Прилива, к северу от Склепа, в поисках ящика с грузом «Пастбищ Дымного Леса».",
    nil, nil,
    "Ящик с грузом «Пастбищ Дымного Леса»", nil, nil, nil,
    originalTitle = "Wreck of the Kestrel"
}

-- ID 26219-26226: Project Epoch переиспользует ванильную цепочку друида
