    "Справедливое вознаграждение",
    "Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.",
    "Принесите комплект перчаток дикого сердца Делиане в Стальгорн.",
    nil, nil, nil, nil, nil, nil,
