    "Справедливое вознаграждение",
    "Ты $gоказался:оказалась; чрезвычайно надежным $gпомощником:помощницей;, $n! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$b$bОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.",
