-- Project Epoch: цепочка Могерна Черноглаза, Пылающие степи (ID 26243-26247) —
-- сборка своего оружия из обсидиана на Черной наковальне (Глубины Черной
-- горы / Город Тенекузни). Переведено по базе pfQuest-epoch 2026-09-06.
RUQL_QUESTS[26243] = {
    "Пылающий самоцвет",
    "Этот самоцвет похож почти на любой другой обломок обсидиана, что валяются по степи, если не считать характерного красноватого отлива. Если поднести его к яркому свету, внутри осколка начинает клубиться и виться дымка, а подержав кристалл в руках подольше, чувствуешь, какой огромный жар он источает.$B$BКто-то в Пылающих степях мог бы заинтересоваться этой находкой.",
    "Найдите того, кто сможет оценить пылающий самоцвет.",
    nil, nil, nil, nil, nil, nil,
    originalTitle = "Blazing Gemstone"
}

RUQL_QUESTS[26244] = {
    "Добыча обсидиана",
    "Слыхал, ребята в Городе Тенекузни делают сплавы из обсидиана с этими паршивцами, превращая их в магическое оружие и всякое такое. Всегда хотел сам попробовать...$B$BЧто скажешь? Обещаю, смастерю тебе что-нибудь стоящее. Просто нужно для начала немного обсидиана с элементалей и порождений войны по всей долине, а там уж перейдём к более интересным реагентам...",
    "Соберите 24 обломка обсидиана с обсидиановых элементалей и порождений войны в Пылающих степях.",
    nil, nil,
    "Обломок обсидиана", nil, nil, nil,
    originalTitle = "Obtaining Obsidian"
}

RUQL_QUESTS[26245] = {
    "Демонический огонь",
    "Ладно, видал этих бесов, что пляшут в тутошней лаве? Мерзкие твари...$B$BКогда-нибудь убивал такого и заглядывал внутрь? Там, где должно быть сердце, — пылающий камень.$B$BПригодится для сплава, если, конечно... не боишься демонического прикосновения на своём оружии!",
    "Соберите 8 тлеющих сердец с бесов в Пылающих степях.",
    nil, nil,
    "Тлеющее сердце", nil, nil, nil,
    originalTitle = "Demonfire"
}

RUQL_QUESTS[26246] = {
    "Драконье пламя",
    "Когда-нибудь задумывался, как драконы дышат огнём? Большинство скажет — магия... но нутро дракона — мечта алхимика.$B$BТам смешиваются реагент за реагентом, а потом дракон выплёвывает всё это через пасть, и смесь воспламеняется, соприкоснувшись с воздухом. Я это к чему клоню...$B$BОдин из базовых реагентов — отличный флюс для нашего сплава, он поможет обсидиану лучше схватиться.$B$BЖелеза, что тебе нужна, красная, густого оттенка, почти светится... и находится она рядом с сердцем. Не с той, что у лёгких.$B$BБольшинство огнедышащих тут опасны, так что тебе может понадобиться помощь. Чем старше особь — тем больше шансов раздобыть железу.",
    "Соберите 12 желёз огненного всполоха с драконов, драконидов или дракончиков в Пылающих степях.",
    nil, nil,
    "Железа огненного всполоха", nil, nil, nil,
    originalTitle = "Dragonfire"
}

RUQL_QUESTS[26247] = {
    "Раскалённое оружие",
    "Так... кажется, я упустил одну маленькую, крошечную, малюсенькую деталь...$B$BСплав готов, но выковать твоё оружие здесь я не смогу! Его нужно придать форму в самом центре Города Тенекузни, на той самой Черной наковальне, в Глубинах Черной горы.$B$BЗнаю, знаю! Просто подумал, что ты будешь чуточку мотивированнее, когда мы соберём все материалы.$B$BТак что... как, готов? Я отправлю тебя с чертежами — такими простыми, что и младенец разберётся! Просто реши по дороге, что хочешь получить, придай форму как сумеешь, а потом принеси обратно сюда, чтобы я закончил дело. И друзей с собой прихвати.",
    "Войдите в Глубины Черной горы и выкуйте основу своего оружия на Черной наковальне в сердце Города Тенекузни.",
    nil, nil,
    "Выковать оружие на Черной наковальне в Городе Тенекузни.", nil, nil, nil,
    originalTitle = "Searing Armaments"
}

-- ID 26227-26263 (кроме 26243-26247 выше): Project Epoch повторяет тот же
-- приём, что и с "Дикое сердце" друида (см. 26219-26226) — для каждого
-- класса берётся идентичный по тексту ванильный квест "Just
-- Compensation"/"Anthion's Parting Words"/"Saving the Best for Last"
-- (Делиана/Стальгорн ↔ Моквар/Оргриммар), только с другим комплектом брони,
-- и разбивается на отдельные ID по одному предмету. D переиспользован из
-- уже официально переведённых стоковых квестов той же пары NPC (см.
-- Data/Generated, поиск "Вальтхалак"), только O адаптирован под конкретный
-- предмет; названия комплектов взяты из уже переведённых O такого же типа
-- ("из светостали" — паладин, "преданности" — жрец, "Стихий" — шаман,
-- "Доблести" — воин). Для ID 26242 (Soulforge Legplates) точного стокового
-- аналога не нашлось — переведено как "Горнило Душ" по аналогии.
