RUQL_QUESTS[26314] = {
    "Ритуал прохлады",
    "Приветствую, $N. Могу я попросить тебя об одной личной услуге?$B$BЗадолго до Третьей войны меня связывали близкие отношения с Джандис Баров, чародейкой немалого таланта. Когда армия Плети обрушилась на Лордерон, часть моих личных вещей осталась у Джандис. Учитывая обстоятельства нашего расставания, я не хочу снова встречаться с её гневом.$B$BНо твоё владение тайной магией не уступает моему, и я верю, что ты сможешь сразиться с ней на равных. Если ты согласишься забрать у неё мои записи о чародейской прохладе, я с радостью поделюсь с тобой их содержимым. Думаю, ты найдёшь Ритуал прохлады настоящей находкой, экономящей уйму времени!$B$BТы и твои спутники найдёте Джандис Баров в подземельях Некроситета, в Западных Чумных землях.",
    "Убейте Джандис Баров в Некроситете и заберите записи верховного чародея Андромата о чародейской прохладе.",
    nil, nil,
    "Записи о чародейской прохладе", nil, nil, nil,
    originalTitle = "Ritual of Refreshment"
}

-- Project Epoch: цепочка Изалнира, Выжженные земли / крепость Фелстоун
-- (ID 26266-26270, 26610, 26625) — сектантский заговор Орды против Легиона
-- в лагере Фелстоун. Переведено по базе pfQuest-epoch 2026-09-06.
RUQL_QUESTS[26266] = {
    "Тёмная литература",
    "Ты ведь с Ордой, верно? Я подыскиваю, к какой стороне примкнуть, и, учитывая все обстоятельства, выбор кажется очевидным...$B$BМоргрия со своим караваном набрела на меня прямо здесь, у моего лагеря. Когда мы оба объяснили, зачем сюда явились... что ж... это будто судьба свела нас в Круговерти — поверишь ли, наши цели полностью совпадают? В общем, мы предварительно договорились: я делюсь сведениями о крепости Фелстоун и средством от гуляющего здесь проклятия — в обмен на гражданство Орды.$B$BЧто до проклятия — у меня есть план, который может сработать, а может и нет. Не постоянное решение, но я могу дать Орде небольшую передышку. То есть — если получу помощь, какую способен оказать только $C.$B$BМне нужны тома у здешних сектантов — именно те, что практикуют магию или ритуалы. Громилы и вышибалы не подойдут. Чем толще том — тем лучше. Объясню подробнее, когда они будут у меня.",
    "Соберите 8 томов тёмных клятв у сектантов в пустошах Выжженных земель.",
    nil, nil,
    "Том тёмных клятв", nil, nil, nil,
    originalTitle = "Dark Literature"
}

RUQL_QUESTS[26267] = {
    "Проклятие наоборот",
    "<Изалнир сутулится, долго вглядываясь в страницы гримуара своими мутными глазами. Наконец он поднимает на тебя взгляд.>$B$BТебе не попадалось что-нибудь похожее на это? Что-то, начертанное на свитке, а то и на камне?$B$B<Изалнир показывает тебе страницу с хаотичными письменами, окружающими зловещего вида руну.>$B$BЧернокнижники используют такие, чтобы играть с проклятием — с болотным огнём — так, как я и представить не мог. Ха, эти глупцы даже используют его в алхимии.$B$BМне понадобится одна из этих рун, чтобы продолжить, и я не думаю, что у кого-то, кроме чернокнижников Фелстоуна, найдётся что-то подобное. В одиночку в крепость соваться слишком опасно, так что возьми с собой друзей. А я пока почитаю дальше, пока ты не вернёшься.",
    "Добудьте руну скверны у чернокнижников внутри крепости Фелстоун.",
    nil, nil,
    "Руна скверны", nil, nil, nil,
    originalTitle = "Reverse Affliction"
}

RUQL_QUESTS[26268] = {
    "Переписывая проклятия",
    "Видишь надпись на этой руне? Она выведена чернилами кужир: весьма мощными и очень труднодобываемыми, даже для чернокнижников. Кровь демона — их основа, отчего чернила отливают чернотой, будто пожирающей свет.$B$BХм... письмена, что они используют, восходят к дальним кругам Бдения Аргуса. Я могу разобрать их достаточно, чтобы внести свои правки, но своих чернил у меня нет.$B$B<Изалнир смотрит на тебя с выжидающей ухмылкой.>$B$BНе раздобудешь немного, будь добр? Они есть у чернокнижников и их прислужников. Ставлю на то, что найдёшь их в шатрах чернокнижников по всей крепости. В хижинах тоже может что-то найтись.",
    "Соберите 5 флаконов чернил кужир по всей крепости Фелстоун.",
    nil, nil,
    "Флакон чернил кужир", nil, nil, nil,
    originalTitle = "Rewriting Curses"
}

RUQL_QUESTS[26269] = {
    "Топливо для душ",
    "Что ты почувствовал, когда держал эту руну? Тошноту? Зуд, который не унять?$B$B<Изалнир кладёт руку на руну и закрывает глаза.>$B$BДля меня это будто стук в голове. Словно... кто-то гремит по клетке. Слыхал я о могучих камнях душ, что вынесли контрабандой из некой пещеры позади Фелстоуна... не так уж сложно предположить, что именно этим и зарядили нашу руну.$B$BОрки внутри этой пещеры — совсем другого поля ягоды, они не снисходят до общения с кем-либо ещё. Тем не менее, иногда воровство, торговля или простая ошибка приводят к тому, что один из их драгоценных камней оказывается не там, где должен быть.$B$BМожет, тебе уже попадались такие? Мне нужен хотя бы один, чтобы мой план принёс плоды. У чернокнижников Фелстоуна, вероятно, найдутся.$B$BЕсли чувствуешь в себе безрассудную смелость, можешь попытать счастья и в самой пещере. Она к западу от центра Фелстоуна, вход обрамлён исполинскими костями. Сам я туда не заходил, но слыхал разные байки...",
    "Найдите камень душ Громболара для Изалнира среди трупов сектантов в крепости Фелстоун.",
    nil, nil,
    "Камень душ Громболара", nil, nil, nil,
    originalTitle = "Soul Fuel"
}

RUQL_QUESTS[26270] = {
    "Далёкий разлад",
    "Время для последнего акта. Твой отряд уже неплохо знаком с опасностями Фелстоуна, так что, надеюсь, это будет не слишком трудно.$B$BПлан таков: отнеси доработанную руну к алтарю на самой верхней террасе южного Фелстоуна и примени её на ритуальном круге. Это лиловая руна, источающая тёмную магию. В теории эта руна вырвет проклятие из его жертв и вернёт его в ритуальный круг — не постоянное решение, как я уже говорил.$B$BЯ не знаю, к чему это приведёт, так что будь готов к чему угодно. Удачи, $N.",
    "Примените изменённую руну скверны на ритуальном круге у высокого алтаря на самой южной, верхней террасе Фелстоуна.",
    nil, nil,
    "Применить изменённую руну скверны на ритуальном круге.", nil, nil, nil,
    originalTitle = "Distant Disruption"
}

RUQL_QUESTS[26610] = {
    "Доклад в Каменор",
    "<Моргрия отдаёт тебе честь и протягивает рваный свиток с блестящей красной печатью.>$B$BСкажу так: миссия удалась, и всё благодаря тебе. От меня — только похвала, $N. Полагаю, тебе захочется поскорее оставить это место позади, так что отнеси этот доклад командиру гарнизона обратно в Каменор.$B$BЕсли славы от истребления врагов Орды тебе не довольно — он позаботится о достойной награде.$B$BПобеда или смерть!",
    "Доложите командиру гарнизона Руагу в Каменоре, в Болоте Печали.",
    nil, nil,
    "Доложить командиру гарнизона Руагу в Каменоре.", nil, nil, nil,
    originalTitle = "Report to Stonard"
}

RUQL_QUESTS[26625] = {
    "РОЗЫСК: Свежеватель душ Грузок",
    "Воины Орды, это призыв к оружию! Старые последователи Гул'дана свили гнездо в крепости Фелстоун, поднимая мёртвых и возрождая тёмное искусство некромантии.$B$BПредводителя этой группы называют Свежевателем душ Грузоком, и, чтобы одолеть его, понадобится закалённый в боях отряд. Ищите его в пещере, обрамлённой костями, внутри крепости Фелстоун, на юге.$B$BПринесите его голову разведчице Моргрии, чтобы получить награду.",
    "Войдите в Громболар внутри крепости Фелстоун и добудьте голову Свежевателя душ Грузока.",
    nil, nil,
    "Убить Свежевателя душ Грузока.", nil, nil, nil,
    originalTitle = "WANTED: Soulflayer Ghruzokh"
}

-- Project Epoch: цепочка Элеанор Лунное Сияние, деревня Звездопад,
-- Зимние Ключи (ID 26271-26275) — огранка звездопадных кристаллов.
RUQL_QUESTS[26271] = {
    "Древняя огранка",
    "Привет! Надеюсь, тебе нравятся Зимние Ключи! Обожаю здешний сухой воздух — после того унылого сумрака Темных берегов. Ты ведь искатель приключений, да?$B$BЯ ученица ювелира, приехала сюда за теми красивыми кристаллами, что повсюду вокруг. Ходят слухи, будто они падают с неба — наверное, отсюда деревня и получила своё название! Только вот инструменты, что я привезла с собой, их не берут. Поверь, я пробовала! Мой лучший шлифовальный станок сломался...!$B$BЭти кристаллы — не новинка, так что наверняка у древних высокородных был свой способ их обрабатывать, правда? Заплачу за всё, что найдёшь! Кел'Терил — к югу, а... Телес'аран — к северо-востоку отсюда, но на дороге туда сидит одна злющая старушенция.",
    "Элеанор Лунное Сияние из деревни Звездопад просит вас найти набор инструментов высокородного ремесленника в одних из более крупных руин высокородных в Зимних Ключах.",
    nil, nil,
    "Набор инструментов высокородного ремесленника", nil, nil, nil,
    originalTitle = "Ancient Gemcutting"
}

RUQL_QUESTS[26272] = {
    "Нам нужен ремонт!",
    "Хм... этот набор и правда старый... пока не чувствую себя уверенно, чтобы им пользоваться.$B$B<Элеанор потирает бровь, разглядывая набор инструментов на удивление внимательным взглядом.>$B$BО, знаю! Я познакомилась с одним гоблином в Круговзоре и одолжила ему кое-какие припасы. Он инженер и должен мне услугу! Ты как раз направляешься в ту сторону? Не против занести это ему? Просто скажи, что это от меня, и что я буду благодарна, если он всё восстановит.",
    "Доставьте набор инструментов высокородного ремесленника Фелноку Стальной Пружине в Круговзор.",
    nil, nil,
    "Доставить набор инструментов Фелноку Стальной Пружине в Круговзор.", nil, nil, nil,
    originalTitle = "We Need Repairs!"
}

RUQL_QUESTS[26273] = {
    "Падающие звёзды",
    "Как увлекательно, $N! Не могу дождаться, когда начну делать украшения. Уверена, Фелнок хороший инженер, но восстановить такую древнюю реликвию — задачка не из лёгких для кого угодно.$B$BА пока — почему бы нам не собрать столько кристаллов, сколько сможем найти? Как всё уладится, я сделаю тебе украшение! Звучит справедливо?",
    "Элеанор Лунное Сияние из деревни Звездопад просит вас собрать 10 звездопадных кристаллов по всем Зимним Ключам.",
    nil, nil,
    "Звездопадный кристалл", nil, nil, nil,
    originalTitle = "Falling Stars"
}

RUQL_QUESTS[26274] = {
    "Мастерство Фелнока",
    "Хорошо, $N. Я бы сама сходила с тобой за набором, но не хочу оставлять все эти самоцветы без присмотра... а вдруг их украдут?$B$BПрости, что взваливаю на тебя столько всего. Обещаю, я это исправлю! Нет, я не ленюсь!",
    "Заберите восстановленный набор инструментов у Фелнока Стальной Пружины в Круговзоре и вернитесь к Элеанор Лунное Сияние в деревню Звездопад в Зимних Ключах.",
    nil, nil,
    "Забрать восстановленный набор инструментов у Фелнока Стальной Пружины.", nil, nil, nil,
    originalTitle = "Felnok's Finesse"
}

RUQL_QUESTS[26275] = {
    "Подарок для тебя!",
    "<Элеанор осторожно пытается придать форму одному из кристаллов.>$B$BХм... может, попрошу Фелнока зайти и объяснить, для чего нужны все эти лишние детали. К счастью, инструменты работают неплохо, так что сейчас я огранюю твой самоцвет!$B$BЭто не займёт много времени! В том ящике, в доме позади меня, лежит мешочек с оправами. Сделаешь для меня последнее одолжение — принесёшь мне этот мешочек? Пожалуйста!",
    "Принесите Элеанор мешочек с оправами для самоцветов из ящика в доме позади неё.",
    nil, nil,
    "Мешочек с оправами для самоцветов", nil, nil, nil,
    originalTitle = "A Gift, For You!"
}

-- Project Epoch: розыскной хаб в Глубинах Черной горы (ID 26276-26280) —
-- разные заказчики из разных зон, объединённые общей целью в BRD.
RUQL_QUESTS[26276] = {
    "Операция «Фаланкс»",
    "Мы всё ещё бьёмся над тем, как эффективнее пробурить ход в Гномреган и начать восстанавливать разрушенное в городе. А для этого нужно больше энергии!$B$BУ меня есть кузен, устроившийся на работу в какую-то лабораторию в Глубинах Черной горы. Там строят големов, что питаются от обсидиановых ядер. Хотела бы изучить одно такое ядро — вдруг оно мне подойдёт.$B$BКузен упоминал старого голема по имени Фаланкс, который как раз использует обсидиановое ядро. Его скоро должны списать — так что никто и не заметит пропажи, если ты его добудешь!",
    "Добудьте обсидиановое ядро у Фаланкса в Глубинах Черной горы для Шони Молчуньи в Штормграде.",
    nil, nil,
    "Обсидиановое ядро", nil, nil, nil,
    originalTitle = "Operation: Phalanx"
}

RUQL_QUESTS[26277] = {
    "Шаман Пламени",
    "В мои обязанности в Круге Земли входит следить за использованием — и злоупотреблением — огненной энергией со стороны шаманов. Недавно я ощутила необычайно резкий, сильный всплеск огня издалека — с Черной горы.$B$BПолагаю, бывший член Круга Земли примкнул к дворфам Черного Железа, что обитают в глубинах горы, и экспериментирует, смешивая энергию огненных элементалей, которой пользуются шаманы, с тайной огненной магией магов.$B$BТакое извращение стихий нельзя оставлять безнаказанным. Мне нужно оставаться здесь и продолжать исследования первородной магии — но, возможно, ты и пара товарищей сможете разобраться с этим шаманом-отступником.$B$BЗовут его Тонака Лорегрейн.",
    "Убейте пироманта Лорегрейна в Глубинах Черной горы, затем вернитесь к Ялуни Хранительнице Пламени в Приют Маршала в кратере Ун'Горо.",
    nil, nil,
    "Пиромант Лорегрейн", nil, nil, nil,
    originalTitle = "Shaman of the Flame"
}

RUQL_QUESTS[26278] = {
    "Наместники Повелителя Огня",
    "Ты доказал мне, что способен одолевать наших врагов и выполнять поручения во имя дела Повелителей Вод. Но до сих пор тебе попадались лишь мелкие противники... пришло время взяться за миссии, что потребуют куда большего мастерства и смелости.$B$BВ глубинах Черной горы дворфы Черного Железа вступили в сговор со слугами Повелителя Огня. Убей двух его главных посланников: лорда Роккора и посла Огнехлёста.$B$BСделай это и докажи мне свою преданность нашему делу.",
    "Убейте лорда Роккора и посла Огнехлёста в Глубинах Черной горы, затем вернитесь к герцогу Гидраксису в Азшару.",
    nil, nil,
    "Лорд Роккор", "Посол Огнехлёст", nil, nil,
    originalTitle = "The Firelord's Lieutenants"
}

RUQL_QUESTS[26279] = {
    "Штука покруче",
    "Капитан Винки — паршивый неудачник. ПАРШИВЫЙ, я сказал!$B$BВинки заявил, что у дворфов Черного Железа есть кое-что стоящее, а я сказал НЕТ! Должно быть что-то получше.$B$BИ я слыхал, что есть.$B$BЗовётся оно Маг. Ма.$B$BМаг. Ма.$B$BМаг. Мус. Магмус! Убей его! Только вот с огнём, наверное, лучше не пробовать.",
    "Убейте Магмуса глубоко в Глубинах Черной горы, затем вернитесь к Орелиусу в Дозор Моргана в Пылающих степях.",
    nil, nil,
    "Убить Магмуса.", nil, nil, nil,
    originalTitle = "The Gooder Stuff"
}

RUQL_QUESTS[26280] = {
    "Заблудший ученик",
    "Ну и ну! $N, мне жаль, что приходится просить помощи у такого искателя приключений, как ты.$B$BЯ только что узнал, что одного из моих бывших учеников видели в Глубинах Черной горы — он там натаскивает демонических псов. А ведь должен убивать демонов, а не якшаться с ними!$B$BХочу отозвать диплом, что когда-то вручил ему — зовут его Гребмар, — но нам, дворфам Стальгорна, нет ходу в город Черного Железа. Не сможешь ли ты сообщить ему эту скверную новость и забрать диплом?",
    "Убейте псаря Гребмара и заберите его диплом охотничьей школы для Ульфира Железной Бороды в Штормграде.",
    nil, nil,
    "Диплом охотничьей школы", nil, nil, nil,
    originalTitle = "The Wayward Student"
}

RUQL_QUESTS[26281] = {
    "Неугасимое пламя",
    "Разглядывая уголёк, ты замечаешь, что он словно живой — пульсирует в руке. Ты вспоминаешь, что слышал, будто Гакин Тёмный Связыватель имел дело со странными предметами вроде этого и, возможно, сумеет разобраться подробнее.$B$BНайти его можно в «Закланном ягнёнке», в квартале магов Штормграда.",
    "Принесите неугасимый уголёк Гакину Тёмному Связывателю в Штормград.",
    nil, nil, nil, nil, nil, nil,
    originalTitle = "An Eternal Flame"
}

-- Project Epoch: хаб копей Блестомути, Тернистая долина/Танарис
-- (ID 26282-26289) — гоблинская Торговая компания против местной фауны.
RUQL_QUESTS[26282] = {
    "Старый долг",
    "Ты похож на предприимчивого типа, готового взяться за работу, не задавая лишних вопросов. Как раз тебя я и искал.$B$BПрежде чем осесть здесь, в Спрингсокете, у меня было своё дело — перевозил товары из одного места в другое. В те времена у меня был «партнёр», который помогал... сглаживать острые углы с таможней и бумажной волокитой. Потом заявилась Торговая компания и переманила его у меня из-под носа, и всё дело развалилось. Я застрял здесь, в пустыне!$B$BХоть всё и наладилось, гоблин такую обиду не забывает. Мне нужно оставаться здесь и приглядывать за своим делом, но если ты не против заглянуть в гости к надзирателю Гримгашу в копях Блестомути, я буду рад тебя наградить.",
    "Найдите надзирателя Гримгаша в копях Блестомути и убейте его.",
    nil, nil,
    "Убить надзирателя Гримгаша.", nil, nil, nil,
    originalTitle = "An Old Debt"
}

RUQL_QUESTS[26283] = {
    "Азотанская реликвия",
    "Перед тобой старый, потрёпанный временем идол, отдалённо напоминающий очертания невообразимо древнего человека. Возможно, им заинтересуется знающий историк — самых видных из них можно найти в Зале исследователей Стальгорна.",
    "Найдите знающего историка в Стальгорне.",
    nil, nil,
    "Найти знающего историка в Стальгорне.", nil, nil, nil,
    originalTitle = "Azothan Relic"
}

RUQL_QUESTS[26284] = {
    "Азотанские реликвии",
    "Говорят, тысячи лет назад тролли воевали с народом, известным лишь как азотане. О них известно совсем немного, однако некоторые из наших более эксцентричных хранителей, включая меня самого, полагают, что здесь кроется куда больше, чем кажется на первый взгляд.$B$BЕсли то, что ты рассказал, правда, и Торговая компания и впрямь наткнулась на тайник их артефактов, крайне важно, чтобы ты принёс их мне. Их место — в музее! Не согласишься ли забраться в их шахту и собрать для меня как можно больше?",
    "Соберите азотанские реликвии в копях Блестомути.",
    nil, nil,
    "Азотанская реликвия", nil, nil, nil,
    originalTitle = "Azothan Relics"
}

RUQL_QUESTS[26285] = {
    "Потерянная трубка Дига",
    "Что за жизнь без парочки слабостей, а, $C?$B$BК несчастью, не могу выкурить свою любимую трубку с тех пор, как потерял её на пляже к востоку от города. Был слегка подшофе, если понимаешь, о чём я, а когда очнулся — увидел здоровенного мурлока, улепётывающего с ней!$B$BПохоже, этот мурлок обжился в копях Блестомути. Если окажешься там и представится случай забрать мою трубку — буду очень благодарен.",
    "Верните потерянную трубку Дига, отобрав её у Мурклурка в копях Блестомути, и принесите её Дигу в Пиратскую Бухту.",
    nil, nil,
    "Потерянная трубка Дига", nil, nil, nil,
    originalTitle = "Deeg's Lost Pipe"
}

RUQL_QUESTS[26286] = {
    "Убить надсмотрщика",
    "У Торговой компании там целый чёртов горнодобывающий комплекс! Неудивительно, что мне так трудно раздобыть поющие кристаллы. Такая махина запросто обрушит устои всех джунглей. Кто-то должен разобраться с этим, пока не стало слишком поздно!$B$BСделай одолжение — устрани конкурентов и принеси мне голову надсмотрщика копей Блестомути. Как только его не станет, я не только смогу наконец получать честную прибыль, но и джунгли не пострадают в процессе!",
