RUQL_QUESTS[26287] = {
    "Радужная чешуя",
    "Раз уж ты так помог мне с заказом на сапоги «Эксельсиор», думаю, стоит помочь и с моим новым экспериментальным фасоном.$B$BЯ расширяюсь — перехожу от кож крокотопов к василискам, но не абы каким. Мне нужен только лучший. Слыхал, Торговая компания нашла в копях Блестомути крупного, блестящего, особенного василиска. Вот он-то мне и нужен. Отправляйся туда и принеси мне его чешую!",
