RUQL_QUESTS[26288] = {
    "Возврат инструментов",
    "Вот в чём дело, $N — пару месяцев назад мне заказали изготовить высококачественные инструменты для одной затеи в Тернистой долине. Надсмотрщик называл её Блесто... как-то там. Блестомуть!$B$BНе знаю, что они там откапывали, но рабочих согнали толпу, а на снабжение шахтёров инструментами золота не пожалели.$B$BС тех пор мне подвернулся куда более выгодный заказ прямо здесь, в Танарисе, и мне нужно вернуть все инструменты, какие только можно, чтобы выполнить его.$B$BЕсли это останется между нами, думаю, ты вполне можешь пойти и «вернуть» инструменты, что я изготовил, у шахтёров Блестомути — и все останутся довольны. Ну, кроме бедолаг из Блестомути, ха-ха. Что скажешь?",
    "Верните 20 инструментов у Торговой компании в копях Блестомути.",
    nil, nil,
    "Возвращённый инструмент", nil, nil, nil,
    originalTitle = "Reclaiming Tools"
}

RUQL_QUESTS[26289] = {
    "Наги-отступники",
    "Как давняя служительница своей королевы, я презираю измену. И всё же наги-заблудшие теряют свой путь, когда их ведут за собой порочные слуги глубин.$B$BЛюбишь мелкие поручения, не так ли, смертный? Как насчёт такого: отправляйся за море, туда, где копают гоблины. Это место в глубине суши, слишком сухое, чтобы мы сами туда наведывались. Гоблины наткнулись на логово заблудших наг, которых ведёт тот, кого зовут Гнаш. Убей слуг Гнаша, а после положи конец и ему самому.$B$BИбо тем, кто бросает вызов королеве, не будет пощады.",
