RUQL_QUESTS[26291] = {
    "Троллиные реликвии",
    "Легенды гласят, что тысячи лет назад тролли воевали с народом, известным лишь как азотане. О них известно немногое, помимо их упорства в бою. Полагаю, здесь кроется куда больше, чем кажется на первый взгляд.$B$BЕсли то, что ты рассказал, правда, и Торговая компания и впрямь наткнулась на тайник их артефактов, крайне важно, чтобы ты принёс их мне. Не согласишься ли забраться в их шахту и собрать для меня как можно больше?",
