RUQL_QUESTS[26292] = {
    "Чудовище из туннеля",
    "Знаю, для эльфийки это необычно, но я обожаю море. Провела немало часов, качаясь на мелководье к востоку от Пиратской Бухты, заводя дружбу с рыбами и птицами. Ни разу не было страшно... до недавнего времени.$B$BЯ заплыла чуть дальше на север, чем обычно, когда какое-то огромное таинственное щупальце поднялось со дна и схватило меня за ногу! Тварь пыталась утащить меня в подводный туннель, но я сопротивлялась. В конце концов, она меня отпустила и скрылась в туннеле... который тут же обвалился за ней.$B$BДумаю, это существо может обитать в тех раскопках, что Торговая компания устроила в холмах к северу от города. Я пыталась их предупредить, но меня не послушали. Прошу, если войдёшь в эти шахты — берегись чудовища! Мне страшно представить, что кто-то ещё столкнётся с ним, ничего не подозревая.",
