    nil, nil,
    "Уничтожить чудовище в копях Блестомути.", nil, nil, nil,
    originalTitle = "Tunnel Monster"
}

-- Project Epoch: цепочка "Fit For A King" (Достойное короля), Вигго и огр
-- Глак — Феralas/Тлеющее ущелье/Мародон (ID 26293-26301), 9 частей.
RUQL_QUESTS[26293] = {
    "Достойное короля",
    "Не похоже, чтобы ты был сильно занят... как насчёт небольшого поручения? Меня прислал сюда картель Стимвиддл, чтобы я приглядел за одним пари. Вот Глак считает, что однажды станет королём Гордоком, как и его отец до него, но нынешний король объявил его предателем и изгнал из Дире Мола. А мы считаем, что у Глака есть всё, чтобы стать королём... с небольшой помощью друзей.$B$BЯ собираюсь выковать для Глака могучее оружие, которым он воспользуется в грядущей битве, а ты добудешь мне для этого все нужные детали. Договорились?$B$BПервым делом мне нужен особый вид волшебного дерева, что можно найти на здешних лесных странниках. Оно лёгкое, но крепкое, как любой металл, — выйдет отличная рукоять.",
    "Соберите ветви странников леса, бродящих по всему Фераласу.",
    nil, nil,
    "Ветвь странника леса", nil, nil, nil,
    originalTitle = "Fit For A King"
}

RUQL_QUESTS[26294] = {
    "Достойное короля",
    "В здешних краях растёт особый вид конопли, из которой я могу свить очень прочную верёвку. Это гарантирует, что даже если Король выпустит оружие из рук, само оружие он не потеряет!$B$BОгры — странный народ. Ходят слухи, что отец Глака, прежний Король, выкурил как-то связку этой травки и забрёл невесть куда прочь от трона. Стоило ему скрыться из виду огров, как они тут же провозгласили нового Короля, положив конец притязаниям Глака на трон.$B$BТак или иначе, конопля растёт у самых рек Фераласа, её можно найти по всему лесу.",
    "Соберите 8 связок болотной конопли для Вигго в Логове Глака.",
    nil, nil,
    "Связка болотной конопли", nil, nil, nil,
    originalTitle = "Fit For A King"
}

RUQL_QUESTS[26295] = {
    "Достойное короля",
    "Важная часть моего плана требует сильно очищенного железа вперемешку с особым сплавом, который ты соберёшь для меня позже. Однако железо в этих краях достать очень непросто!$B$BНо у меня есть обходной путь: много не нужно, так что мы можем добыть его прямо здесь, из зверей Фераласа.$B$BВот небольшая штуковина, которую я называю «Гемовак Макс». Ослабь зверя и высоси всё железо прямо из его крови! Собрав достаточно флаконов, я получу довольно железа, чтобы с ним работать. К сожалению, в каждом флаконе так мало, что придётся устроить добрую старомодную бойню зверья.",
    "Соберите 20 флаконов крови зверей с ослабленных зверей в Фераласе.",
    nil, nil,
    "Флакон крови зверя", nil, nil, nil,
    originalTitle = "Fit For A King"
}

RUQL_QUESTS[26296] = {
    "Достойное короля",
    "А теперь перейдём к... менее приятным вещам. Не зря я ждал, пока ты не втянешься в это дело, чтобы попросить тебя об этом. К юго-востоку отсюда ты найдёшь Кишащую глубину. Там обитают шустрые твари, которых некоторые прозвали силитидами.$B$BИзвестно, что порой они принимают руду за еду и покрывают её липкой слизью. Знаешь, что бывает, когда они её полностью... переваривают и... выводят?$B$BА получаем мы мешанину руд, что каким-то образом складывается в новый сплав. Не спрашивай меня как — я никогда не горел желанием заглянуть внутрь одной из них, чтобы это выяснить. Меня заботит одно — чтобы ты добыл мне эти сплавы для нового оружия Глака.",
    "Соберите 12 кусков силитидового сплава в Кишащей глубине, в Фераласе.",
    nil, nil,
    "Силитидовый сплав", nil, nil, nil,
    originalTitle = "Fit For A King"
}

RUQL_QUESTS[26297] = {
    "Достойное короля",
    "Мы почти у цели — осталось создать это королевское оружие. Затор сейчас прост: нужно создать и поддерживать нужный жар. Здешняя кузница отлично подходит для обычной низкосортной работы, какой обычно занимаются огры, но её жара не хватит, чтобы расплавить эти сплавы и соединить их с железом.$B$BК несчастью, это значит, что жар придётся принести к нам. Далеко на востоке, в Восточных королевствах, ты найдёшь Тлеющее ущелье.$B$BЭто такое место, где течёт лава, плавится камень, а элементали бродят на воле. Мне нужно, чтобы ты собрал их огненные эссенции и принёс их мне.$B$BС этими эссенциями я смогу разогреть кузницу до нужного жара.",
    "Соберите бурлящий расплавленный камень и обжигающую огненную эссенцию с земляных и огненных элементалей в Тлеющем ущелье.",
    nil, nil,
    "Бурлящий расплавленный камень", "Обжигающая огненная эссенция", nil, nil,
    originalTitle = "Fit For A King"
}

RUQL_QUESTS[26298] = {
    "Достойное короля",
    "Жар — лишь половина уравнения, $C. Нам нужно уметь умерять пламя и управлять жаром, позволяя сплавам медленно плавиться, соединяться и становиться чем-то совершенно новым. Тебе повезло — далеко посылать тебя не придётся.$B$BПрямо на побережье Фераласа ты найдёшь водных элементалей, что впитали в себя охлаждающую эссенцию самого моря. Ступай и собери её как можно больше, и мы используем её в процессе ковки, чтобы не спалить весь лагерь дотла!",
    "Соберите соленую охлаждающую эссенцию с водных элементалей на побережье Фераласа.",
