RUQL_QUESTS[26299] = {
    "Достойное короля",
    "Так, забудь про лёгкий денёк. Есть только одно место, где, как я слышал, может найтись то, что нам нужно: родина кентавров, известная как Мародон.$B$BГлубоко в оранжевых пещерах ты найдёшь чрезвычайно могущественного водного элементаля по имени «Ноксион», чья эссенция послужит куда более достойным реагентом для оружия такой мощи.$B$BРискнёшь жизнью и конечностями, чтобы добыть для меня его эссенцию? Обещаю, всё окупится, как только Глак воцарится в Дире Моле!",
    "Войдите в Мародон и убейте Ноксиона. Заберите его эссенцию и принесите Вигго в Фералас.",
