RUQL_QUESTS[26300] = {
    "Достойное короля",
    "Эти два неповоротливых олуха позади меня — Бряк и Тюк. Умом они не блещут, зато отменно колотят по наковальне здоровенным молотом, так что, на мой взгляд, они не глупее среднего кузнеца.$B$BПока они куют оружие и страдают от жара, мне понадобится, чтобы ты усмирял пламя и охлаждал их эссенцией Ноксиона. Не дай ограм перегреться, а не то всё было зря.",
