RUQL_QUESTS[26302] = {
    "Источник порчи",
    "Устные предания гласят, что эти земли когда-то были пышными и цветущими, но освобождение кентавров принцессой Терадрас в Мародоне вызвало катастрофу, создавшую те земли, что мы видим вокруг. Моя цель — восстановить эти края с помощью Диби и Келли.$B$BОдин из ключевых элементов, что нам нужно изучить подробнее, — образец самой принцессы. Её гибель не только положит конец дальнейшей порче, но и, изучив её вблизи, мы, возможно, сумеем эту порчу обратить вспять.$B$BСпустись в Мародон от моего имени и добудь для меня образец. Я щедро заплачу.",
