-- Project Epoch: цепочка "Attunement to the Core" (Привыкание к Ядру),
-- герцог Гидраксис, Огненные Недра (ID 26303-26307), 5 частей.
RUQL_QUESTS[26303] = {
    "Привыкание к Ядру",
    "О, гляди-ка, это $N. Уже видел, как ты проходишь мимо, не замечая, насколько особенное это место. В паре шагов от того места, где я стою, — устойчивый разрыв в реальности, ведущий глубоко в сердце Черной горы, в место, известное как Огненные Недра. Это место великого зла, но и великой славы для таких смельчаков, как ты. Хочешь взглянуть?$B$BКонечно, хочешь, но для смертного вроде тебя соваться туда без подготовки слишком опасно. К счастью, я здесь, чтобы подтолкнуть тебя в верном направлении.$B$BОтыщи гидраксийских Повелителей Вод, что обитают вдоль побережья Азшары. Они кровно заинтересованы в твоём успехе.",
    "Найдите герцога Гидраксиса на острове у побережья Азшары.",
    nil, nil,
    "Найти герцога Гидраксиса на острове у побережья Азшары.", nil, nil, nil,
    originalTitle = "Attunement to the Core"
}

RUQL_QUESTS[26304] = {
    "Привыкание к Ядру",
    "Огненные Недра — логово наших смертельных врагов, огненных элементалей. Если их не остановить, они станут набирать силу, пока не подожгут весь Азерот.$B$BБушующее сердце горы слишком горячо даже для союзников Повелителя Огня, дворфов Черного Железа. Но если ты выполнишь мою просьбу, я одарю тебя благословением, что позволит выдержать невыносимый жар в сердце вулкана.$B$BСперва мне понадобятся стихийные материалы для ритуала. Собери огонь стихий, воду стихий, немного огненного цвета и немного зимнего укуса. Если не найдёшь всё это в мире сам, полагаю, смертные продают такое на каком-нибудь торговом узле.",
    "Принесите 5 огненных цветов, 5 зимних укусов, огонь стихий и воду стихий герцогу Гидраксису на острове у побережья Азшары.",
    nil, nil,
    "Огненный цвет", "Зимний укус", "Огонь стихий", "Вода стихий",
    originalTitle = "Attunement to the Core"
}

RUQL_QUESTS[26305] = {
    "Привыкание к Ядру",
    "Далее нам понадобятся напитанные эссенции могучих существ, связанных с огнём и льдом.$B$BРядом с Алтарём Бурь в Пылающих степях, в водопаде лавы, ты найдёшь Торида. Убить его и добыть его огненное ядро — благо для всего мира.$B$BЧто до мороза — тебе нужно будет убить моего кузена Кинайса в Зимних Ключах. Он обитает у замёрзшего водопада к югу от озера Кел'Терил.$B$BЭто прискорбная, но необходимая жертва.",
    "Принесите огненное ядро Торида и морозное ядро Кинайса герцогу Гидраксису на острове у побережья Азшары.",
    nil, nil,
