}

RUQL_QUESTS[26306] = {
    "Привыкание к Ядру",
    "Теперь тебе нужно собрать реагенты, чтобы привыкнуть к жару горы. Нам понадобятся образцы жара и резонанса из самих Огненных Недр — или настолько близко к ним, насколько ты сможешь безопасно подобраться.$B$BВойди в оплот дворфов Черного Железа, известный как Глубины Черной горы. Проберись в самый низ, и ты найдёшь их плавильню. Наполни этот изолированный флакон обжигающей лавой неподалёку.$B$BЗатем перейди через мост к самому Ядру и собери осколок со стены рядом.$B$BНе обманывайся, смертный, это опасное задание, которое не стоит выполнять в одиночку. Возвращайся ко мне после, если выживешь.",
