    "Испытание для готовых",
    "Рад встрече, $C $N. Недавно я побывал в Подгороде и имел случай побеседовать с Падшим рыцарем.$B$B<Паладин посмеивается.>$B$BХотел бы я когда-нибудь узнать её настоящее имя — как-то непрофессионально называть её так. Тем не менее, она высоко отзывалась о твоём потенциале и просила отправить тебя к ней на испытания. Отправляйся в Подгород и разыщи её.",
