RUQL_QUESTS[26309] = {
    "Испытание для готовых",
    "Я не та, кем была прежде, $C $N. Рыцарь Серебряной Длани, паладин великой добродетели. Защитница истины и справедливости. Теперь я лежу здесь, в утробе Подгорода, вылавливая хилых тварей в этой слизи.$B$BНо ты — ты выказываешь готовность сражаться с тьмой, несмотря на то, что эта тьма покоится и в твоей собственной душе. Я хочу испытать тебя, если ты согласен.",
