RUQL_QUESTS[26310] = {
    "Испытание для готовых",
    "Для твоего первого испытания тебе нужно будет отправиться далеко на северо-восток Тирисфальских лесов. Это к востоку от Бастиона Алого ордена, но берегись подходить слишком близко к самому Бастиону — ты пока недостаточно силён для этого места. Ты найдёшь небольшую каменную тропу, ведущую к кладбищу.$B$BНа том кладбище ты найдёшь трёх призраков паладинов. При жизни они действовали одной командой, а после смерти были похоронены в общем месте упокоения. Я чувствую, они всё ещё цепляются за этот мир. Ступай и освободи их, чтобы они наконец обрели покой.",
    "Победите трёх призраков бывших паладинов на кладбище к востоку от Бастиона Алого ордена. Вернитесь к Падшему рыцарю в Подгород, когда упокоите духов.",
