RUQL_QUESTS[26316] = {
    "Правовое наследие Лордерона",
    "При жизни я была правоведом, и после смерти хотела бы продолжить эти изыскания, попутно исследуя куда более широкие темы. У меня нет времени самой отправляться за книгами в руины Лордерона, но подозреваю, у тебя оно найдётся.$B$BПринеси мне определённые тома из руин Стратхольма и школы Некроситета, и я смогу совмещать обязанности сказителя с личными увлечениями.",
