    "Ищешь работу, мон? Мне нужна храбрая душа, чтобы отправиться на юг, в топь.$B$BВ Затонувшем храме ты найдёшь верховных жрецов и знахарей. Эти тролли пишут на свитках безумные пророчества самого Кровавого бога Хаккара. Я слежу за его последователями, и эти свитки помогли бы мне в этом. Что скажешь?",
