RUQL_QUESTS[26319] = {
    "Наследие знаний",
    "Путник, прости за беспокойство, но твоё имя облетело весь Дом знати, и я ждала героя с именем, достойным визита в крепость.$B$BС падением и Кель'Таласа, и Даларана немалая часть знаний моего народа была утрачена. Однако Кирин-Тор содержал библиотеку в тюремной крепости Оплот Барадин на острове Тол Барад. Там хранится немало томов, которые я всей душой хотела бы сохранить.$B$BНе окажешь ли ты мне услугу в этом деле? Я щедро тебя вознагражу.",
