RUQL_QUESTS[26325] = {
    "Закопанное сокровище",
    "Эта неприметная куча земли, кажется, не скрывает никакого сокровища. Копаясь в рыхлой земле, ты будто нащупываешь пальцами край сундука — но ощущение тут же пропадает.$B$BВозможно, чтобы откопать сундук, нужен особый инструмент?",
