RUQL_QUESTS[26326] = {
    "В чистилище",
    "Среди сокровищ в сундуке капитана Чёрностена — странная молочно-белая сфера, что пульсирует зловещим красным светом. Касаясь её гладкой поверхности, ты, как ни странно, чувствуешь необъяснимое спокойствие. Возможно, стоит разузнать об этом предмете подробнее.",
