RUQL_QUESTS[26327] = {
    "В чистилище",
    "$C, теперь ты связан с Оком Палета, проклятым магией более могущественной, чем та, что держит жителей этого острова в чистилище — а нас связал Свет за нашу роль в жестокостях лагерей для интернированных Южнобережья.$B$BНе случайность, что капитан Чёрностен выбрал именно этот остров, чтобы спрятать своё сокровище. Он немало настрадался, прежде чем его завербовали во флот капёров Южнобережья. Было по-своему справедливо, что мы охраняли его сокровище в качестве искупления.$B$BЭта история не должна была тебя коснуться, но теперь ты увяз в ней по уши. Если не хочешь, чтобы его ошибки взяли верх над твоей жизнью, тебе придётся распутать проклятие — то, с чем не справился сам Чёрностен.$B$BЯ не знаю подробностей о том, как Око попало к Чёрностену, но полагаю, тебе придётся проследить его путь до самого источника, чтобы разорвать проклятие, что теперь связывает его с тобой. Чёрностен прибыл на этот остров с тремя членами своей команды. Разыщи их, если не хочешь, подобно Чёрностену, поддаться безумию.",
    "Найдите бывших членов команды капитана Чёрностена и узнайте, что они скажут о происхождении Ока Палета.",
    nil, nil,
    "Найти бывших членов команды капитана Чёрностена.", nil, nil, nil,
    originalTitle = "Into Purgatory"
}

RUQL_QUESTS[26328] = {
    "В чистилище",
    "Значит, трое членов команды сказали, что сокровище в Фераласе, в пещере, где обитают наги?$B$BЯ ничего не знаю о Калимдоре, чтобы дать тебе дальнейший совет, но если обыщешь прибрежные пещеры тех земель, не сомневаюсь, ты найдёшь то, что ищешь.$B$BИ раздобудь ещё одну из тех лопат, которыми откопал здесь сундук. Уверен, она тебе понадобится.$B$BПрощай, $C. Надеюсь, у нас не будет повода встретиться снова.",
