RUQL_QUESTS[26329] = {
    "Сны о другой жизни",
    "Вместо сокровища и разгадки происхождения проклятия «Оковывателя Пелены» ты находишь записку, объясняющую, что Чёрностен спрятал сокровище в другом месте, чтобы защитить свою команду. Этот благородный жест обрекает тебя и дальше носить проклятое Око Палета.$B$BТолько возлюбленная Чёрностена знает истинное местонахождение сокровища. Найти её — твоя единственная надежда избавиться от проклятия.",
    "Найдите общего друга Чёрностена и его возлюбленной. Быть может, в судовых журналах Чёрностена есть подсказки о том, с кем он дружил?",
    nil, nil,
    "Найти общего друга Чёрностена и его возлюбленной.", nil, nil, nil,
    originalTitle = "Dreams of Another Life"
}

RUQL_QUESTS[26330] = {
    "Сны о другой жизни",
    "Эта ферма была нашей мечтой. Думаю, я всегда знала, что он никогда по-настоящему сюда не вернётся. Быть капёром — опасное дело, а уж когда он подался в настоящее пиратство...$B$BПонятия не имею, как Чёрностену удалось перевезти сюда сокровище, но он спрятал его в пещере неподалёку. Полагаю, это был его последний подарок мне, но добраться до него я так и не смогла. Там обитают духи из-за Пелены. Они попытаются отбросить нас назад. Но если у тебя хватило сил одолеть в бою мою любовь и пережить проклятие, чтобы добраться сюда, — быть может, хватит сил одолеть и их.$B$BСкажи мне, когда будешь готов отправиться в путь.",
    "Защитите Пару из клана Мрачный Тотем, пока она ведёт вас к сокровищнице.",
    nil, nil, nil, nil, nil, nil,
    originalTitle = "Dreams of Another Life"
}

RUQL_QUESTS[26333] = {
    "Полцарства за корабль",
    "Плавать я не умею и уж точно не собираюсь тратить время, чтобы учиться сейчас! Мне нужны детали, чтобы построить собственную лодку — совсем небольшую, так что прошу немногого.$B$BВот список деталей; бегом дуй за ними в своей непромокаемой броне и принеси мне всё это. Чем скорее пойдёшь, тем скорее вернёшься, тем скорее снимешь проклятие, и тем скорее я высплюсь в нормальной постели.$B$BОй — а где всё это найти? Ну, слыхала, в Западных Чумных землях есть лесопилка, может, там что раздобудешь. Руническая ткань просто валяется где ни попадя, верно? Нить продают торговцы, а кувшины смолы найдутся у других пиратов.",
    "Добудьте припасы, что просила Уинки для постройки корабля, и принесите их на её остров в Танарисе.",
    nil, nil,
    "Отрез рунической ткани", "Катушка нити", "Грубый лес", "Кувшин смолы",
    originalTitle = "My Kingdom for a Ship"
}

RUQL_QUESTS[26334] = {
    "Полцарства за корабль",
    "Голыми руками корабль не построишь! Мне нужны подходящие инструменты, чтобы собрать все эти детали, и мне нужно, чтобы ты их достал. Пока тебя не было, я мечтала о сыре и работала над загаром, а не училась плавать. Мечтать важно! Это то, что двигает вперёд. И много ли ты видела загорелых гномов? Моя золотистая кожа произведёт настоящий фурор.$B$BВ общем, мне нужны кузнечный молот, искровой гаечный ключ, 50 горстей медных болтов и гномий лобзик. Опытный инженер помог бы с частью этого, но лобзик можно достать только в одном месте — в Гномрегане!",
    "Добудьте инструменты, что нужны Уинки для постройки собственного корабля.",
    nil, nil,
    "Кузнечный молот", "Искровой гаечный ключ", "Горсть медных болтов", "Гномий лобзик",
    originalTitle = "My Kingdom for a Ship"
}

RUQL_QUESTS[26335] = {
    "Месть Стьюэла",
    "Как я уже говорил, мой отец отдал жизнь, чтобы спасти Чёрностена и остальную орочью команду от заключения. Орков, что служили под началом моего отца, забрали из лагерей для интернированных, а после разгрома флота капёров Южнобережья вернули обратно в те же лагеря. Отец добивался их свободы, но получил отказ от судьи Телграма и надзирательницы Лорин Ремки.$B$BТелграм давно мёртв, но, полагаю, Ремка ещё жива. Прислушайся она к голосу разума — отцу не пришлось бы пытаться вызволить орков из лагеря, и он бы не погиб за это. Совесть не даст мне покоя, пока она не заплатит за его смерть, но я понятия не имею, где она сейчас. Ремка держала личную рабыню-орчиху по имени Гри'кик. При лагере у Ремки также был помощник по имени Уорик. Не знаю, живы ли они оба до сих пор, но если найдёшь хоть одного из них, возможно, это выведет тебя на след Ремки.",
    "Выясните, жива ли Лорин Ремка.",
    nil, nil,
    "Гри'кик", "Питер Уорик", nil, nil,
    originalTitle = "Stewel's Revenge"
}

RUQL_QUESTS[26336] = {
    "Месть Стьюэла",
    "Хотел бы я положиться на систему правосудия, чтобы она вынесла надлежащее наказание, но мало надежды, что правители Штормграда станут заботиться о преступлениях, совершённых в Лордероне много лет назад.$B$BОтец не одобрил бы моё желание отомстить. Он даже взял с меня обещание не поднимать руку на этих глупцов, если операция пойдёт не так. Есть способ сдержать букву этого обещания и сохранить чистую совесть. Ты станешь моей рукой мести. Сделай это, и я расскажу тебе то, что ты хочешь знать.$B$BЛорин Ремка должна умереть. Кровь за кровь.",
    "Убейте Лорин Ремку.",
    nil, nil,
    "Убить Лорин Ремку.", nil, nil, nil,
    originalTitle = "Stewel's Revenge"
}

RUQL_QUESTS[26344] = {
    "Услуга за услугу",
    "Догадываюсь, ты ищешь остаток сокровищ, из которых происходит эта сфера, и у меня хорошие новости — их закопали одним большим тайником неподалёку от места, где мы захватили тот корабль. Плохие новости в том, что у меня есть только часть координат. Чёрностен разделил их между мной, Уинкс и Джуниором. Так что придётся поговорить с ними, чтобы узнать остальное.$B$BНо сперва — у меня небольшая проблема с одной соперницей из другого картеля. С тех пор как я ушёл от команды Чёрностена, я подрабатываю на Черноводных разбойников, и не раз сталкивался с начальницей Оглторп из Торговой компании. Устал оглядываться каждый раз, стоит мне выйти за пределы Пиратской Бухты. Убери её для меня, и я расскажу тебе, что хочешь знать.$B$BУ неё где-то здесь, в Тернистой долине, своя маленькая база, но я не знаю, где именно.",
    "Найдите начальницу Оглторп в Тернистой долине и устраните её.",
    nil, nil,
    "Убить начальницу Оглторп.", nil, nil, nil,
    originalTitle = "You Scratch My Back..."
}

-- Project Epoch: заговор пиратов вокруг Оплота Барадин, Тол Барад
-- (ID 26331-26332, 26337-26343).
RUQL_QUESTS[26332] = {
    "Пиратский грабёж",
    "Слушайте сюда! Мне передали слово от... ну, скажем так, от союзника, что у Тол Барада якобы разворачивается морская атака.$B$BЭтот остров гроша ломаного не стоит, так что уже подозрительно, что вообще прислали такое донесение.$B$BОтправляйся в бухту Фалдира и поговори с капитаном Стальное Брюхо, скажи, что это я тебя послал. Там-то тебе всё и объяснят.",
    "Найдите капитана Стальное Брюхо в бухте Фалдира, в Нагорье Арати.",
    nil, nil,
    "Найти капитана Стальное Брюхо в бухте Фалдира.", nil, nil, nil,
    originalTitle = "Plundering Pirates"
}

RUQL_QUESTS[26331] = {
    "Пиратский грабёж",
    "Три луны назад наш дозорный заметил паруса и корабли на горизонте. Он утверждал, что уже видел эти флаги раньше, но, похоже, слишком напуган, чтобы вспомнить, где или с кем. Вскоре после того, как их заметили, над водой прокатился грохот пушечных залпов.$B$BВ той стороне лишь один остров: Тол Барад, дом старой тюрьмы Кирин-Тора. Что кому-то там понадобилось? Это набег? Побег?$B$BМне любопытно, а моя суеверная команда напугана. Ты можешь помочь! Поговори со Смотрителем гнездовья Хокинсом и попроси доставить тебя на Тол Барад. Мне нужен разведчик, чтобы осмотреть остров и доложить, что там творится.",
    "Возьмите грифона у Смотрителя гнездовья Хокинса и разведайте пиратское нападение на Тол Барад.",
    nil, nil,
    "Разведать пиратское нападение на Тол Барад.", nil, nil, nil,
    originalTitle = "Plundering Pirates"
}

RUQL_QUESTS[26337] = {
    "Некромант и наследница",
    "Привет, $C. Если ты ищешь тайную работёнку, уверяю, ты обратился по адресу.$B$BСлыхал, на тюремном острове Оплот Барадин случился небольшой побег. Там содержатся пара узников, которым я предпочёл бы не давать сбежать. Оба — могущественные чародеи, способные обрушить разрушение на Подгород. А уж лишних некромантов, разгуливающих на свободе, нам совсем не нужно.$B$BЕсли не против прогуляться до бухты Фалдира в Нагорье Арати и запрыгнуть на рейс до Тол Барада, я хорошо отблагодарю тебя за то, чтобы Астилос и Назрасаш никогда не покинули остров.",
    "Войдите в Оплот Барадин на острове Тол Барад и убейте Астилоса Полого и Назрасаш.",
    nil, nil,
    "Астилос Полый", "Назрасаш", nil, nil,
    originalTitle = "The Necromancer and the Scion"
}

RUQL_QUESTS[26338] = {
    "Возможное падение Оплота Барадин",
    "Как гранд-адмирал флота Штормграда, я получаю донесения о всевозможных происшествиях и тёмных делишках в открытом море. Недавно с острова-крепости Тол Барад пришло тревожное донесение. Возможно, пираты захватили старую тюрьму Кирин-Тора.$B$BПока этот слух ничем не подтверждён. Мне нужен кто-то, кто отправится на Тол Барад и оценит обстановку. Ты, похоже, справишься — твой Альянс нуждается в тебе, искатель приключений.$B$BПрежде чем отправиться, загляни в SI:7. Возможно, у них найдутся более подробные сведения.",
    "Найдите кого-нибудь в SI:7, кто расскажет вам больше о нынешнем положении дел в Оплоте Барадин.",
    nil, nil,
    "Найти кого-нибудь в SI:7.", nil, nil, nil,
    originalTitle = "The Possible Fall of Baradin Hold"
}

RUQL_QUESTS[26339] = {
    "Возможное падение Оплота Барадин",
    "На острове Тол Барад находится тюрьма Оплот Барадин — но Барадин не просто тюрьма. Там держали взаперти одних из худших существ в мире. Есть даже такое, с которым не сумел справиться сам Кезан!$B$BТак что да, нам нужно знать, захватили ли пираты тюрьму — а если захватили, нужно ещё и что-то с этим сделать. Оставляю тебе решать, как лучше действовать, как только окажешься на месте.$B$BКстати, если не знаешь, как туда добраться, придётся отправиться в бухту Фалдира в Нагорье Арати. Тамошний мастер полётов с радостью тебя отправит.",
    "Проверьте обстановку в Оплоте Барадин на острове Тол Барад — правдивы ли слухи о пиратском нападении.",
    nil, nil,
    "Проверить обстановку в Оплоте Барадин.", nil, nil, nil,
    originalTitle = "The Possible Fall of Baradin Hold"
}

RUQL_QUESTS[26340] = {
    "Возможное падение Оплота Барадин",
    "Рензик велел тебе взять дело в свои руки, если слухи подтвердятся.$B$BПроще всего исправить положение — устранить пиратов, что сейчас удерживают Оплот Барадин.$B$BТебе придётся пробиться с боем через всю тюрьму, чтобы восстановить порядок.",
    "Убейте пиратов, ответственных за нападение на Оплот Барадин: Глагута, Калипсо и пиратского лорда Чёрностена.",
    nil, nil,
    "Глагут", "Калипсо", "Пиратский лорд Чёрностен", nil,
    originalTitle = "The Possible Fall of Baradin Hold"
}

RUQL_QUESTS[26341] = {
    "Возможное падение Оплота Барадин",
    "Герой Орды, твои вожди нуждаются в твоей помощи!$B$BНа острове Тол Барад находится тюрьма Оплот Барадин — там держали взаперти одних из худших тварей в мире. Есть даже такая, с которой не сумел справиться сам Кезан!$B$BХодят слухи, что пираты захватили тюрьму. Нужно проверить. Оставляю тебе решать, как лучше действовать, как только окажешься на месте.$B$BКстати, если не знаешь, как туда добраться, придётся отправиться в бухту Фалдира в Нагорье Арати. Тамошний мастер полётов с радостью тебя отправит.",
    "Проверьте обстановку в Оплоте Барадин на острове Тол Барад — правдивы ли слухи о пиратском нападении.",
