    "Волджин велел тебе взять дело в свои руки, если слухи подтвердятся.$B$BПроще всего исправить положение — устранить пиратов, что сейчас удерживают Оплот Барадин.$B$BТебе придётся пробиться с боем через всю тюрьму, чтобы восстановить порядок.",
