RUQL_QUESTS[26343] = {
    "Все демоны, которых я когда-то любил",
    "Привет, $C. Если ты ищешь тайную работёнку, уверяю, ты обратился по адресу.$B$BСлыхал, на тюремном острове Оплот Барадин случился небольшой побег. Там содержатся пара узников, которым я предпочёл бы не давать сбежать. Есть неплохой шанс, что они станут искать меня, а мне такой хаос в Штормграде совсем ни к чему.$B$BЕсли не против прогуляться до бухты Фалдира в Нагорье Арати и запрыгнуть на рейс до Тол Барада, я хорошо отблагодарю тебя за то, чтобы Моррумус и Дак'мал никогда не покинули остров.",
