-- Project Epoch: цепочка "Диски Норганнона" / Ульдум (ID 26345-26352) —
-- Лига исследователей выходит на след Скрижалей Ульдума.
RUQL_QUESTS[26346] = {
    "Захватывающая находка",
    "Некоторое время назад Лига исследователей получила артефакт, называемый Дисками Норганнона. Мы пытаемся извлечь из Дисков хоть какие-то сведения, и чтобы продвинуться дальше, нам нужен знаток языка таурахе.$B$BНам удалось найти таурен-контакта, готового с нами сотрудничать, и нужен посыльный, чтобы встретиться с ней. Слышал о тебе немало хорошего в городе, так что хотел бы, чтобы ты встретился с Калетакой Зимний Утёс в таверне «Сломанный Киль» в Кабестане. Если мы правы, эти Диски могут привести к открытию древнего комплекса Ульдум!",
    "Встретьтесь с Калетакой Зимний Утёс в Кабестане, чтобы обсудить Диски Норганнона.",
    nil, nil,
    "Встретиться с Калетакой Зимний Утёс в Кабестане.", nil, nil, nil,
    originalTitle = "An Exciting Discovery"
}

RUQL_QUESTS[26345] = {
    "Хорошие новости",
    "У меня отличные новости, $N! Лиге исследователей удалось расшифровать некоторые руны на Дисках Норганнона. Как ни странно, они схожи с рунами древнего языка таурахе.$B$BНам удалось найти таурен-контакта, готового с нами сотрудничать, и мы хотели бы, чтобы ты поработал с ней. Она согласилась приехать из Громового Утёса в Кабестан, чтобы встретиться с тобой. Найди Калетаку Зимний Утёс в тамошней таверне, и мы станем на шаг ближе к тому, чтобы открыть Ульдум!",
    "Встретьтесь с Калетакой Зимний Утёс в Кабестане, чтобы обсудить Диски Норганнона.",
    nil, nil,
    "Встретиться с Калетакой Зимний Утёс в Кабестане.", nil, nil, nil,
    originalTitle = "The Good News"
}

RUQL_QUESTS[26347] = {
    "Хорошие новости",
    "Признаюсь честно, немного нервно встречаться с $R лицом к лицу, но моя мать не из тех, кто позволяет распрям между фракциями мешать стремлению к знаниям.$B$BОна, впрочем, беспокоилась в дороге сюда — ей казалось, что кто-то подозрительный нас преследует. Она решила не ждать здесь и просила передать тебе, что отправилась в Оскверненный лес. Раз она пешком, уверена, ты её нагонишь.$B$BЯ волнуюсь за неё, $R, но уверен, мама сама может о себе позаботиться.",
    "Найдите Калетаку Зимний Утёс где-то на дороге между Кабестаном и Оскверненным лесом.",
    nil, nil,
    "Найти Калетаку Зимний Утёс между Кабестаном и Оскверненным лесом.", nil, nil, nil,
    originalTitle = "The Good News"
}

RUQL_QUESTS[26348] = {
    "Плохие новости",
    "Тело Калетаки Зимний Утёс обчистили от всех ценностей. Похоже, на неё напали из засады — на руках нет следов обороны. Единственный порез, ровно поперёк горла, говорит о том, насколько умел был её убийца.$B$BТы уже собираешься уходить, когда замечаешь неподалёку в грязи одинокий странный отпечаток копыта. Ты запоминаешь его детали, понимая, что должен вернуться к Мулину Зимний Утёс в Кабестан и сказать ему, что подозрения его матери о слежке оказались верны — к несчастью для всех.",
    "Вернитесь к Мулину Зимний Утёс в Кабестан с плохими новостями.",
    nil, nil,
    "Вернуться к Мулину Зимний Утёс с плохими новостями.", nil, nil, nil,
    originalTitle = "The Bad News"
}

RUQL_QUESTS[26349] = {
    "Плохие новости",
    "<Пока Мулин пытается успокоиться, ты описываешь отпечаток копыта, что видел в грязи.>$B$BХотел бы я помочь тебе, но сейчас не могу сосредоточиться. Но прежде чем ты уйдёшь — у меня есть кое-что от матери, что тебе следует получить, $R.$B$BМама сказала мне, если с ней что-то случится, отдать тебе эту записку. Надеюсь, она поможет тебе с тем, для чего она была тебе нужна.$B$BПрости, если скажу, что больше никогда не хочу видеть ни одного $R.",
    "Отнесите зашифрованную записку Калетаки Верховному исследователю Магелласу в Стальгорн.",
    nil, nil,
    "Зашифрованная записка Калетаки", nil, nil, nil,
    originalTitle = "The Bad News"
}

RUQL_QUESTS[26350] = {
    "Снова хорошие новости",
    "Я займусь расшифровкой послания Калетаки, но пока тебя не было, другие члены Лиги исследователей совершили прорыв в определении местонахождения Скрижалей Ульдума.$B$BПоговори с историком Карником, если хочешь узнать больше.",
    "Поговорите с историком Карником в Зале исследователей в Стальгорне.",
    nil, nil,
    "Поговорить с историком Карником в Зале исследователей.", nil, nil, nil,
    originalTitle = "The Good News Again"
}

RUQL_QUESTS[26351] = {
    "Снова хорошие новости",
    "Лига исследователей расшифровала несколько фрагментов сведений, указывающих на то, что Скрижали Ульдума хранились там, где постоянно стоит дым. Кроме того, в тексте часто встречаются слова «ущелье» и «пещера».$B$BКазалось бы очевидным, что речь о Тлеющем ущелье, но не забывай — эти диски были созданы задолго до того, как призвали Рагнароса. Тлеющего ущелья тогда попросту не существовало.$B$BА вот Ущелье Мрачного Шёпота в Зимних Ключах — существовало.$B$BМы хотели бы, чтобы ты применил свои немалые таланты и обыскал Ущелье Мрачного Шёпота на предмет любых следов Скрижалей Ульдума. Доложи о находках.",
    "Обыщите Ущелье Мрачного Шёпота в Зимних Ключах в поисках подсказки о местонахождении Скрижалей Ульдума.",
    nil, nil,
    "Обыскать Ущелье Мрачного Шёпота.", nil, nil, nil,
    originalTitle = "The Good News Again"
}

RUQL_QUESTS[26352] = {
    "Снова плохие новости",
    "Я знаю, что ты ищешь, и видел, с какой доблестью ты это искал. Будь уверен, я говорю это не просто так — я видел, чем готовы жертвовать смертные ради стремления к знаниям.$B$BНо будь осторожен: ты не готов к встрече со Скрижалями Ульдума. Ты не готов к тому, что ждёт за теми вратами. Даже Титаны не были готовы к тому, что нашли там, — потому Скрижали и Диски разделили и рассеяли по всему свету.$B$BЕсли ты продолжишь идти по этому следу, это высвободит невыразимую погибель. Ступай, $R. Здесь этому квесту конец. Советую тебе найти новый.",
    "Вернитесь к историку Карнику в Стальгорн с посланием Заклинателя земли.",
    nil, nil,
    "Послание Заклинателя земли", nil, nil, nil,
    originalTitle = "The Bad News Again"
}

-- Дворфийский вариант той же цепочки "Диски Норганнона" (Хедриг/Нелли
-- Железный Камень, Громовой Утёс). В O 26353 указана Пиратская Бухта, а в
-- D — Кабестан; несостыковка есть уже в исходной базе pfQuest-epoch,
-- переведено как есть по каждому полю отдельно.
RUQL_QUESTS[26354] = {
    "Захватывающая находка",
    "Некоторое время назад сказители получили артефакт, называемый Дисками Норганнона. Мы пытаемся извлечь из Дисков хоть какие-то сведения, и чтобы продвинуться дальше, нам нужен знаток дворфийского языка.$B$BНам удалось найти дворфийского контакта, готового с нами сотрудничать, и нужен посыльный, чтобы встретиться с ним. Слышал о тебе немало хорошего в городе, так что хотел бы, чтобы ты встретился с Хедригом Железный Камень в таверне «Сломанный Киль» в Кабестане. Если мы правы, эти Диски могут привести к открытию древнего комплекса Ульдум!",
    "Встретьтесь с Хедригом Железный Камень в Кабестане, чтобы обсудить Диски Норганнона.",
    nil, nil,
    "Встретиться с Хедригом Железный Камень в Кабестане.", nil, nil, nil,
    originalTitle = "An Exciting Discovery"
}

RUQL_QUESTS[26353] = {
    "Хорошие новости",
    "У меня отличные новости, $N! Сказителям удалось расшифровать некоторые руны на Дисках Норганнона. Они написаны на древнем дворфийском языке.$B$BНам удалось найти дворфийского контакта, готового с нами сотрудничать, и мы хотели бы, чтобы ты встретился с ним. Он согласился приехать из Стальгорна в Кабестан, чтобы встретиться с тобой. Найди Хедрига Железный Камень в тамошней таверне, и мы станем на шаг ближе к тому, чтобы открыть Ульдум!",
    "Встретьтесь с Хедригом Железный Камень в Пиратской Бухте, чтобы обсудить Диски Норганнона.",
    nil, nil,
    "Встретиться с Хедригом Железный Камень.", nil, nil, nil,
    originalTitle = "The Good News"
}

RUQL_QUESTS[26355] = {
    "Хорошие новости",
    "Скажу честно, малость нервно встречать $R лицом к лицу, но батя не из тех, кто позволяет распрям между фракциями мешать стремлению к знаниям.$B$BОн, впрочем, беспокоился в дороге сюда. Думал, что кто-то следит за нами и идёт следом, так что отправился один. Просил передать тебе, что пошёл в Оскверненный лес. Раз он пешком, уверен, ты его нагонишь.$B$BЯ волнуюсь за него, $R, но уверен, батя сам может о себе позаботиться.",
