-- Project Epoch: вводная цепочка охотничьего питомца, Златоземье/Штормград
-- (ID 26409-26413). Переведено по базе pfQuest-epoch 2026-09-06.
RUQL_QUESTS[26409] = {
    "Путь охотника",
    "Здравствуй, юный охотник. Ты, похоже, достаточно искусен, чтобы совладать со зверем и обучить его быть твоим спутником.$B$BТебе нужно повидать Джеймса Корбетта в Златоземье. Он укажет тебе путь к тому, чтобы обзавестись собственным питомцем.",
    "Поговорите с Джеймсом Корбеттом в Златоземье.",
    nil, nil,
    "Поговорить с Джеймсом Корбеттом в Златоземье.", nil, nil, nil,
    originalTitle = "The Hunter's Path"
}

RUQL_QUESTS[26410] = {
    "Приручение зверя",
    "Привет, $Gпарень:девчонка;! Значит, хочешь узнать, как обзавестись собственным питомцем?$B$BЧто ж, давай сосредоточимся на том, что тебе наверняка интересно: на питомце!$B$BЛучший способ научиться — попробовать разных зверей в роли спутников и понять, что тебе по душе. Так что найди твердокожего вепря и приручи его этим жезлом.",
    "Используйте жезл приручения, чтобы приручить твердокожего вепря. Потренируйтесь, затем верните жезл приручения Джеймсу Корбетту в Златоземье.",
    nil, nil,
    "Твердокожий вепрь", nil, nil, nil,
    originalTitle = "Taming the Beast"
}

RUQL_QUESTS[26411] = {
    "Приручение зверя",
    "Эти твердокожие вепри довольно неуклюжи; может, хочешь чего-то с изяществом побольше? Что ж, тогда у меня есть кое-что как раз для тебя. К востоку отсюда водятся крупные волки, которых называют рыскунами. Как и изящно резной лук, за их красивой наружностью скрывается грозный боец, способный наносить огромный урон. Ты увидишь, что они куда проворнее и быстрее вепря, которого приручил.$B$BВозьми этот жезл и посмотри, понравится ли тебе рыскун.",
    "Используйте жезл приручения, чтобы приручить рыскуна. Потренируйтесь, затем верните жезл приручения Джеймсу Корбетту в Златоземье.",
    nil, nil,
    "Рыскун", nil, nil, nil,
    originalTitle = "Taming the Beast"
}

RUQL_QUESTS[26412] = {
    "Приручение зверя",
    "Может, хочешь зверя, что представляет собой немногим больше грубой силы? Молодой лесной медведь — отличный спутник для начинающего охотника вроде тебя, и найти его можно к востоку от Златоземья. Вот жезл приручения; попробуй этого зверя в роли питомца и посмотри, понравится ли он тебе!$B$BКогда вернёшься, я обучу тебя навыкам, которые понадобятся, чтобы приручить животное по твоему выбору; этот зверь будет встречать те же испытания, что и ты, и получать опыт вместе с тобой. Я также покажу, как призывать его и отпускать по своему желанию.",
    "Используйте жезл приручения, чтобы приручить молодого лесного медведя. Потренируйтесь, затем верните жезл приручения Джеймсу Корбетту в Златоземье.",
    nil, nil,
    "Молодой лесной медведь", nil, nil, nil,
    originalTitle = "Taming the Beast"
}

RUQL_QUESTS[26413] = {
    "Обучение зверя",
    "$N, теперь у тебя есть сила приручать питомца, но тебе нужно ещё обрести навыки, чтобы его обучить.$B$BОтправляйся в Штормград и найди Дворфийский квартал. Там тебе нужно поговорить с одним из наших самых почтенных укротителей зверей, Хоуи Хиллом. Он даст тебе умение обучать нового питомца, так что ступай, $Gпарень:девчонка;!$B$BХоуи — дружелюбный малый, никаких сложностей с тем, чтобы заслужить его одобрение, у тебя не будет. Удачи, $N.",
    "Поговорите с Хоуи Хиллом в Штормграде.",
    nil, nil,
    "Поговорить с Хоуи Хиллом в Штормграде.", nil, nil, nil,
