RUQL_QUESTS[26414] = {
    "Потрёпанное письмо",
    "Меня попросили сразу передать это тебе, как только ты вернёшься из лагерей кобольдов, $N. Похоже, это письмо от Сеси, нашего местного наставника охотников. Я бы не медлил с тем, чтобы прочесть его, прежде чем заняться другими делами здесь, в аббатстве.",
