-- Project Epoch: цепочки телепорт-заклинаний магов, Терамор/Каменор
-- (ID 26416-26421, 26424-26427) и вариант "Ritual of Refreshment" в
-- Подгороде (26422-26423).
RUQL_QUESTS[26416] = {
    "Дверь в Терамор",
    "Здравствуй снова, $N. Полагаю, мой город не раз пригодился тебе как место для телепортации? Если так, как насчёт того, чтобы вместо этого создать свой собственный портал? Задача на этот раз куда сложнее, но у меня для тебя припасена ещё одна награда сверх самого заклинания.$B$BСперва мне нужно, чтобы ты отправился к Темному порталу в Выжженных землях. Этот проклятый портал — вход в родной мир орков, Дренор, но на самом деле это уже второй Темный портал. Первый был уничтожен архимагом Кадгаром в попытке остановить вторжение орков во время Второй войны. Рядом с новым порталом всё ещё можно найти фрагменты того, старого. Собери для меня три небольших фрагмента, и мы продолжим.",
    "Соберите 3 фрагмента первого Темного портала рядом с новым Темным порталом в Выжженных землях, затем вернитесь к леди Джайне Праудмур в Терамор.",
    nil, nil,
    "Фрагмент первого Темного портала", nil, nil, nil,
    originalTitle = "Doorway to Theramore"
}

RUQL_QUESTS[26417] = {
    "Дверь в Терамор",
    "Отлично сработано, эти фрагменты прекрасно подойдут для тво...$B$B<Леди Джайна кашляет.>$B$BЧуть не забыла, что это должно оставаться сюрпризом! Далее нам нужны пять зелёных кристаллов силы из кратера Ун'Горо. Они разбросаны по всей округе. Если ты там ни разу не бывал, спуститься можно с юго-запада Танариса. Хотя веселее будет просто наложить медленное падение и прыгнуть прямо в кратер!",
    "Соберите 5 зелёных кристаллов силы в кратере Ун'Горо, затем вернитесь к леди Джайне Праудмур в Терамор.",
    nil, nil,
    "Зелёный кристалл силы", nil, nil, nil,
    originalTitle = "Doorway to Theramore"
}

RUQL_QUESTS[26418] = {
    "Дверь в Терамор",
    "Что ж, пора раскрыть цель этих поручений! Помимо того, что я научу тебя создавать портал в Терамор, я ещё и подарю тебе головной убор — что-то вроде короны. Хотя, наверное, это не такой уж подарок, раз тебе пришлось самому добывать почти все материалы для него, но у меня их просто не было под рукой! Идея этой короны пришла мне в голову не так давно. В ней используются камни, тронутые Нижним миром, усиленные раздробленными кристаллами силы. Надеюсь, всё получится!$B$BНо нужен ещё один компонент. Связывать подобные камни воедино — не самое распространённое знание, но я читала, что подробное объяснение есть в книге могущественного чародея по имени Сит'рель, что некогда жил в Городе Тенекузни — то есть в Глубинах Черной горы. Если сможешь отправиться туда и добыть этот том, мы сможем завершить корону.",
    "Отправляйтесь в Глубины Черной горы и одолейте Семёрку, чтобы добыть том Сит'реля, затем вернитесь к леди Джайне Праудмур в Терамор.",
    nil, nil,
    "Том Сит'реля об искусстве связывания", nil, nil, nil,
    originalTitle = "Doorway to Theramore"
}

RUQL_QUESTS[26419] = {
    "Дверь в Каменор",
    "А, $C! Рад тебя видеть, есть у меня к тебе предложение. Вместо того чтобы просто телепортироваться в Каменор, почему бы не создать портал для твоих союзников? Мне нужна лишь твоя помощь, чтобы кое-что создать. Если всё пойдёт по моей теории, я даже позволю тебе оставить этот предмет себе.$B$BЕсли это звучит стоящим делом, отправляйся на юг отсюда, в Выжженные земли, и собери фрагменты изначального Темного портала, разбросанные по земле рядом с нынешним порталом. Не подходи слишком близко к самому порталу, если только не жаждешь смерти.",
    "Соберите 3 фрагмента первого Темного портала рядом с новым Темным порталом в Выжженных землях, затем вернитесь к Лоррину Лисьему Огню в Каменор.",
    nil, nil,
    "Фрагмент первого Темного портала", nil, nil, nil,
    originalTitle = "Doorway to Stonard"
}

RUQL_QUESTS[26420] = {
    "Дверь в Каменор",
    "Следующее задание немного дальше, на далёком Калимдоре. Отправляйся в кратер Ун'Горо и собери 5 зелёных кристаллов силы. Найти их можно где угодно — весь кратер усыпан кристаллами силы. Их природа малоизучена, и именно поэтому я прошу тебя об этом. Если ты там ни разу не бывал, вниз в кратер ведёт тропа на юго-западе Танариса. А если чувствуешь себя достаточно безрассудным — просто наложи медленное падение и прыгни в кратер.$B$BПостарайся, чтобы тебя не съели.",
    "Соберите 5 зелёных кристаллов силы в кратере Ун'Горо, затем вернитесь к Лоррину Лисьему Огню в Каменор.",
    nil, nil,
    "Зелёный кристалл силы", nil, nil, nil,
    originalTitle = "Doorway to Stonard"
}

RUQL_QUESTS[26421] = {
    "Дверь в Каменор",
    "Используя эти камни, подвергнутые чудовищной энергии Нижнего мира, и раздробленные кристаллы силы, я надеюсь создать для тебя что-то вроде короны. Причина, по которой я собираюсь отдать её тебе, если всё получится, проста — мне она попросту ни к чему. Я лишь хочу узнать, верна ли моя теория. А такому искателю приключений, как ты, она точно пригодится. Можешь хоть выбросить её потом, мне всё равно.$B$BНо нужен ещё один компонент. Умений у меня много, но связывание камней, увы, не из их числа. Я знаю дворфийского чародея по имени Сит'рель, что некогда жил в Городе Тенекузни. Это в Глубинах Черной горы, если ты не знал. У Сит'реля есть том со сведениями, которые мне нужны. Если сможешь отправиться туда и добыть этот том, мы сможем завершить корону.",
    "Отправляйтесь в Глубины Черной горы и одолейте Семёрку, чтобы добыть том Сит'реля, затем вернитесь к Лоррину Лисьему Огню в Каменор.",
    nil, nil,
    "Том Сит'реля об искусстве связывания", nil, nil, nil,
    originalTitle = "Doorway to Stonard"
}

RUQL_QUESTS[26422] = {
    "Ритуал прохлады",
    "Приветствую, $N. Могу я попросить тебя об одной личной услуге?$B$BЗадолго до Третьей войны меня связывали близкие отношения с Джандис Баров, чародейкой немалого таланта. Когда армия Плети обрушилась на Лордерон, часть моих личных вещей осталась у Джандис. Учитывая обстоятельства нашего расставания, я не хочу снова встречаться с её гневом.$B$BНо твоё владение тайной магией не уступает моему, и я верю, что ты сможешь сразиться с ней на равных. Если ты согласишься забрать у неё мои записи о чародейской прохладе, я с радостью поделюсь с тобой их содержимым. Думаю, ты найдёшь Ритуал прохлады настоящей находкой, экономящей уйму времени!$B$BТы и твои спутники найдёте Джандис Баров в подземельях Некроситета, в Западных Чумных землях.",
    "Убейте Джандис Баров в Некроситете и заберите записи Бетора Ледяного Осколка о чародейской прохладе.",
    nil, nil,
    "Записи о чародейской прохладе", nil, nil, nil,
    originalTitle = "Ritual of Refreshment"
}

RUQL_QUESTS[26423] = {
    "Ритуал прохлады",
    "Приветствую, $N. Ты весьма преуспел в обучении, и, полагаю, мне почти нечему больше тебя научить. Готов поспорить, тебе уже надоело призывать еду и питьё для союзников, верно? Если я прав, думаю, стоит поговорить с верховным чародеем Андроматом в Штормграде. Уверен, он знает способ получше.",
    "Поговорите с Бетором Ледяным Осколком в квартале магов Подгорода.",
