RUQL_QUESTS[26424] = {
    "Глаза для Терамора",
    "А, здравствуй, $C! Есть у меня к тебе предложение — как насчёт того, чтобы уметь телепортироваться в Терамор? Вижу, ты довольно учёный и повидавший мир маг, так что не сомневаюсь, обучить тебя будет несложно.$B$BСперва мне нужно, чтобы ты отправился в далёкое Болото Печали в Восточных королевствах, к самому побережью. Там ты найдёшь илистых ползунов. Собери четырнадцать их глаз, да проследи, чтобы они остались целыми! Когда вернёшься, я объясню, зачем они понадобятся для следующего задания.",
    "Добудьте 14 глаз илистых ползунов на побережье Болота Печали в Восточных королевствах, затем вернитесь к леди Джайне Праудмур в Терамор.",
    nil, nil,
    "Глаз илистого ползуна", nil, nil, nil,
    originalTitle = "Eyes for Theramore"
}

RUQL_QUESTS[26425] = {
    "Тайная амальгама",
    "Чудесно, $N. Теперь о том, зачем тебе понадобились эти глаза. Слышал ли ты когда-нибудь об элементальной амальгаме? Сильно сомневаюсь! Это тайные конструкты, напитанные стихийной энергией, способные принимать облик элементалей. Сами по себе они не элементали, но отличить их непросто.$B$BТак вот, одна такая обитает в подвале цитадели Оплот, прямо здесь, в Тераморе. Не знаю, кто её туда поместил, но боюсь, рано или поздно это создаст проблему. Собранные тобою глаза должны выявить этого «элементаля», позволив тебе его одолеть. Я могла бы одолеть его и сама, но чувствую, что тебе эта битва пойдёт на пользу. Удачи! Я в тебя всецело верю.",
    "Используйте эликсир тайного зрения в подвале цитадели Оплот в Тераморе, затем одолейте элементальную амальгаму. После этого вернитесь к леди Джайне Праудмур в Терамор.",
    nil, nil,
    "Одолеть элементальную амальгаму в цитадели Оплот.", nil, nil, nil,
    originalTitle = "Arcane Amalgam"
}

RUQL_QUESTS[26426] = {
    "Смердящее захолустье",
    "Эй, ты, похоже, ты довольно учёный $C. Наконец-то не тупой орк! Знаешь, случайно, что такое элементальная амальгама? Нет? Хм, значит, не такой уж учёный...$B$B<Лоррин ненадолго умолкает и переставляет что-то на столе.>$B$BВот что скажу: если поможешь мне, без лишних вопросов, я научу тебя телепортироваться сюда, в Каменор, идёт? Может, это и смердящее захолустье, но хотя бы место полезное.$B$BОтправляйся в далёкие Пылевые топи и собери четырнадцать глаз сухотопских крокотопов. В идеальном состоянии! Найдёшь их на южной оконечности топей.",
    "Добудьте 14 глаз сухотопских крокотопов у сухотопских крокотопов на юге Пылевых топей в Калимдоре, затем вернитесь к Лоррину Лисьему Огню в Каменор.",
    nil, nil,
    "Глаз сухотопского крокотопа", nil, nil, nil,
    originalTitle = "Backwater Stinkhole"
}

RUQL_QUESTS[26427] = {
    "Тайная амальгама",
    "Я использовал собранные тобой глаза, чтобы сварить эликсир тайного зрения. Примени его в южной орочьей норе, чуть западнее отсюда. Он призовёт тайное создание — элементальную амальгаму. Твоя задача — одолеть её.$B$BЕсли вернёшься живым, так и быть, объясню, что это за тварь, но если гадаешь, я ли её туда поместил — нет, не я. Понятия не имею, кто это сделал.",
    "Используйте эликсир тайного зрения в южной орочьей норе за пределами Каменора, затем одолейте элементальную амальгаму. После этого вернитесь к Лоррину Лисьему Огню в Каменор.",
    nil, nil,
    "Одолеть элементальную амальгаму в орочьей норе.", nil, nil, nil,
    originalTitle = "Arcane Amalgam"
}

RUQL_QUESTS[26428] = {
    "Освящённый свиток",
    "Прежде чем ты уйдёшь, мне только что передал этот свиток посыльный. Он от местного наставника паладинов Дарнелла. Взгляни — не так уж много паладинов в рядах Отрёкшихся.",
    "Прочитайте освящённый свиток и поговорите с Дарнеллом в Мёртвой просеке.",
