-- Project Epoch: паладинская цепочка боевого скакуна Отрёкшихся
-- (ID 26429-26439) — продолжение линии Падшего рыцаря из "Trial of the
-- Willing"/"Materials of the Light".
RUQL_QUESTS[26429] = {
    "Во главе угла — жертва",
    "Я знаю, что ты ищешь, $C $N, и сделаю всё, что в моих силах, чтобы помочь. Обычным путём это не сделать, так что нам придётся заручиться помощью неортодоксального союзника.$B$BЧтобы подготовить себя к этому испытанию, тебе сперва нужно принести жертву.$B$BНам понадобится тотем духов для того, что будет дальше. Хоть использован он будет во имя добра и справедливости, за то, чтобы разлучить с ним шамана, полагается достойная компенсация.$B$BОтправляйся в Громовой Утёс и поговори с Мулном Земляная Ярость на Обрыве стихий, к западу от города. Возьми с собой достаточно монет, чтобы возместить потерю тотема, — это покажет твою готовность пожертвовать мирским богатством ради стремления к праведности.",
    "Отправляйтесь в Громовой Утёс и получите тотем духов у Мулна Земляная Ярость на Обрыве стихий. Это потребует пожертвования в 150 золота.",
    nil, nil,
    "Получить тотем духов у Мулна Земляная Ярость.", nil, nil, nil,
    originalTitle = "Emphasis on Sacrifice"
}

RUQL_QUESTS[26430] = {
    "Дабы явить надлежащий суд",
    "Возьми тотем духов с моим благословением, $C. Я сама использовала его, чтобы заглянуть за Пелену, и он сослужит тебе добрую службу в предстоящих делах.$B$BПолагаю, на этом твои дела здесь закончены. Вернись к Падшему рыцарю в Подгород со своим трофеем.",
    "Верните тотем духов Падшему рыцарю в Подгород.",
