RUQL_QUESTS[26431] = {
    "Изгнание духа",
    "Этот тотем позволит тебе видеть духов — призраков существ, застрявших между миром живых и миром мёртвых. Один из них тебе поможет, но сперва ты должен свершить над ним суд за деяния, что он совершил при жизни.$B$BВ саду за Бастионом Алого ордена, что зовётся Террасой Покоя, воткни тотем духов в землю. Он позволит тебе увидеть то, что недоступно смертному глазу. Разыщи дух павшего паладина. Сразись с этим духом, и он будет должен тебе долг ратной чести. Когда закончишь, дух заговорит с тобой.",
    "Отправьтесь на Террасу Покоя за Бастионом Алого ордена и используйте тотем духов, чтобы сделать видимыми призраков, что населяют руины. Разыщите дух павшего паладина и одолейте его.",
    nil, nil,
    "Одолеть дух павшего паладина на Террасе Покоя.", nil, nil, nil,
    originalTitle = "Exorcising the Spirit"
}

RUQL_QUESTS[26432] = {
    "Работа мастера",
    "Хочешь призвать скакуна, чтобы въехать на нём в битву? Это мечта каждого паладина, как только он заслужит такую привилегию.$B$BНе представляю, как такое создание, как ты, могло бы заслужить то же самое, но если ты твёрдо намерен попытаться, тебе понадобятся доспехи для скакуна.$B$BМои доспехи выковали лучшие кузнецы Стратхольма. Сомневаюсь, что у тебя будет доступ к их мастерским, но среди рядов мёртвых наверняка найдётся кто-то умелый.",
    "Спросите у Падшего рыцаря, кто в Орде достаточно искусен, чтобы изготовить ваши доспехи скакуна.",
    nil, nil,
    "Спросить у Падшего рыцаря, кто может изготовить доспехи скакуна.", nil, nil, nil,
    originalTitle = "The Work of a Master"
}

RUQL_QUESTS[26433] = {
    "Багровый чертёж",
    "Значит, кузнецы Алого ордена куют свои доспехи скакунов в Стратхольме? Внутри Алого бастиона есть молотобоец с немалой славой. Осмелюсь предположить, именно он этим и занимается. По крайней мере, это наш лучший шанс раздобыть чертежи.$B$BЕсли сумеешь добыть чертежи, тебе нужно будет отнести их в часовню Последней Надежды. Уверен, они написаны на человеческом языке — Атурк без помощи такое не прочтёт.",
    "Войдите в Стратхольм и убейте багрового молотобойца, чтобы добыть чертежи багровых доспехов скакуна. Отнесите их квартирмейстеру Миранде Бричлок в часовню Последней Надежды.",
