    "Переведённый чертёж",
    "Я завершила для тебя свои записи. Похоже, этот чертёж предназначен для паладинских доспехов скакуна. Поздравляю с этим достижением, $C. Удачи тебе в дальнейшем. Надеюсь снова увидеть тебя здесь, наносящим удар по злу, что бродит по этой земле.",
