RUQL_QUESTS[26435] = {
    "Сбор припасов",
    "Согласно чертежу, для этих доспехов нужно четыре компонента: руническая ткань для подкладки, слитки аркана для обшивки, слёзы Артаса для духовной настройки и святая вода Стратхольма для духовного наполнения.$B$BПусть будет пять вещей — мне ведь ещё нужно заплатить за работу. В плату войдёт и труд, и изготовленное вручную седло со стременами.$B$BКак только доставишь припасы, я смогу завершить доспехи. Немедленно примусь за седло.",
    "Принесите 40 рунической ткани, 6 слитков аркана, 10 слёз Артаса, 5 флаконов святой воды Стратхольма и 150 золота Атурку Наковальне в Долину Чести Оргриммара.",
    nil, nil,
    "Руническая ткань", "Слиток аркана", "Слёзы Артаса", "Святая вода Стратхольма",
    originalTitle = "Collection of Goods"
}

RUQL_QUESTS[26436] = {
    "Лучшая работа Атурка",
    "<Атурк вытирает пот со лба, сияя от гордости.>$B$BКогда я начинал учиться ремеслу на Дреноре, я и не думал, что однажды стану ковать доспехи для скакуна святого воина. Но это, мой отрёкшийся друг, одна из лучших моих работ. Спасибо, что доверил мне сделать всё в лучшем виде.$B$BНе сомневаюсь, твой наставник захочет сам оценить качество работы. Отнеси доспехи ему и возвращайся, если возникнут какие-то нарекания.",
    "Отнесите доспехи скакуна из аркана паладину Алого ордена на Террасу Покоя в Тирисфальских лесах. Вам понадобится тотем духов, чтобы их увидеть.",
