}

RUQL_QUESTS[26437] = {
    "Духи скакунов",
    "Твоим доспехам нужно особое благословение — от подобающего духа. Неподалёку, в руинах Андорала, я чувствую духов лошадей, что оказались в ловушке там во время падения города. Освободи их, и они вознаградят тебя, даровав твоим доспехам благословение.$B$BТы должен освободить их всех, $N, иначе благословение не сработает. А оно, полагаю, и не сработает — для такого исчадия, как ты.",
    "Отправьтесь в руины Андорала и освободите духов скакунов из тамошних конюшен. Поговорите с духами скакунов, чтобы благословить доспехи из аркана. Затем вернитесь к паладину Алого ордена на Террасу Покоя в Тирисфальских лесах. Вам понадобится тотем духов, чтобы их увидеть.",
