    "Освободить духов скакунов в руинах Андорала.", nil, nil, nil,
    originalTitle = "Equine Spirits"
}

RUQL_QUESTS[26438] = {
    "Зерцало прорицания",
    "Если ты и впрямь намерен довести это до конца, нам нужен способ поднять павшего скакуна. Тотем духов, которым ты пользуешься, чтобы говорить со мной, ляжет в основу этого устройства.$B$BОстальные компоненты — два алмаза. Они должны быть противопоставлены друг другу по яркости, чтобы пробить Пелену Светом. Отсюда — мне нужен азеротский алмаз и безупречный чёрный алмаз. С ними в качестве фокусирующих средств тотем духов сможет стать маяком для твоей божественной воли.$B$B<Паладин Алого ордена вздрагивает.>$B$BПослушать только себя — говорю с тобой, будто ты достойное существо.",
    "Принесите азеротский алмаз и безупречный чёрный алмаз паладину Алого ордена на Террасу Покоя в Тирисфальских лесах. Вам понадобится тотем духов, чтобы их увидеть.",
    nil, nil,
    "Азеротский алмаз", "Безупречный чёрный алмаз", nil, nil,
    originalTitle = "The Divination Scryer"
}

RUQL_QUESTS[26439] = {
    "Суд и искупление",
    "Возьми эту суму — в ней вещи, что понадобятся тебе для этого испытания.$B$BИспользуй зерцало прорицания в сердце подвала Великого оссуария, чтобы призвать проклятых духов, над которыми нужно свершить суд. Мудро используй свои суждения в этом испытании — они окажутся куда весомее, чем ты думаешь. После духов явится рыцарь смерти; одолей его и верни утраченную душу скакуна. Лишь тогда, $N, ты сможешь искупить её и возложить свои доспехи на нового скакуна!",
    "Используйте зерцало прорицания в сердце подвала Великого оссуария в Некроситете. Это призовёт духов, над которыми вам предстоит свершить суд. Одолев этих духов, вы призовёте рыцаря смерти Тёмного Жнеца. Одолейте его и верните утраченную душу павшего скакуна.\n\nОтдайте искупленные души скакуна и благословенный зачарованный доспех скакуна Падшему скакуну Тёмного Жнеца.",
